window.HAN_CAU=[["丁","Đinh","Can Đinh, thứ 4 trong 10 thiên can; hành Hỏa."],["丑","Sửu","Chi Sửu, thứ 2 trong 12 địa chi; hành Thổ."],["丙","Bính","Can Bính, thứ 3 trong 10 thiên can; hành Hỏa."],["乙","Ất","Can Ất, thứ 2 trong 10 thiên can; hành Mộc."],["亥","Hợi","Chi Hợi, thứ 12 trong 12 địa chi; hành Thủy."],["午","Ngọ","Chi Ngọ, thứ 7 trong 12 địa chi; hành Hỏa."],["卯","Mão","Chi Mão, thứ 4 trong 12 địa chi; hành Mộc."],["壬","Nhâm","Can Nhâm, thứ 9 trong 10 thiên can; hành Thủy."],["子","Tý","Chi Tý, thứ 1 trong 12 địa chi; hành Thủy."],["寅","Dần","Chi Dần, thứ 3 trong 12 địa chi; hành Mộc."],["己","Kỷ","Can Kỷ, thứ 6 trong 10 thiên can; hành Thổ."],["巳","Tỵ","Chi Tỵ, thứ 6 trong 12 địa chi; hành Hỏa."],["庚","Canh","Can Canh, thứ 7 trong 10 thiên can; hành Kim."],["戊","Mậu","Can Mậu, thứ 5 trong 10 thiên can; hành Thổ."],["戌","Tuất","Chi Tuất, thứ 11 trong 12 địa chi; hành Thổ."],["未","Mùi","Chi Mùi, thứ 8 trong 12 địa chi; hành Thổ."],["甲","Giáp","Can Giáp, thứ 1 trong 10 thiên can; hành Mộc."],["申","Thân","Chi Thân, thứ 9 trong 12 địa chi; hành Kim."],["癸","Quý","Can Quý, thứ 10 trong 10 thiên can; hành Thủy."],["辛","Tân","Can Tân, thứ 8 trong 10 thiên can; hành Kim."],["辰","Thìn","Chi Thìn, thứ 5 trong 12 địa chi; hành Thổ."],["酉","Dậu","Chi Dậu, thứ 10 trong 12 địa chi; hành Kim."],["九地","Cửu địa","Chín loại đất, chín cách ứng"],["九變","Cửu biến","Biết biến hoá"],["作戰","Tác chiến","Cái giá của việc đánh"],["兵勢","Binh thế","Thế động, chính và kỳ"],["原始","Nguyên thủy","Cái gốc ban đầu"],["地形","Địa hình","Thế đất và lỗi của người chỉ huy"],["始計","Thủy kế","Tính toán trước khi làm"],["安禮","An lễ","Yên trong lễ"],["正道","Chính đạo","Đường ngay"],["火攻","Hỏa công","Đánh bằng lửa, dừng đúng lúc"],["用間","Dụng gián","Biết trước nhờ người"],["素書","Tố Thư",""],["虛實","Hư thực","Chỗ trống và chỗ đặc"],["行軍","Hành quân","Đi, đóng và đọc dấu hiệu"],["謀攻","Mưu công","Thắng bằng mưu, không phá"],["軍形","Quân hình","Thế vững không thể thua"],["軍爭","Quân tranh","Giành lợi thế"],["遵義","Tuân nghĩa","Theo nghĩa mà làm"],["孫子兵法","Tôn Tử binh pháp",""],["本德宗道","Bản đức tông đạo","Đức làm gốc, đạo làm chủ"],["朱子家訓","Chu Tử gia huấn",""],["求人之志","Cầu nhân chi chí","Chí của người cầu đạo"],["勿營華屋勿謀良田","Vật doanh hoa ốc, vật mưu lương điền.","Đừng mải xây nhà cao cửa rộng, đừng mưu toan gom ruộng tốt."],["施惠無念受恩莫忘","Thi huệ vô niệm, thụ ân mạc vong.","Làm ơn cho người thì đừng nhớ; chịu ơn của người thì chớ quên."],["夫欲為人之本不可無一焉","Phù dục vi nhân chi bản, bất khả vô nhất yên.","Muốn làm cái gốc của con người, không thể thiếu một thứ nào trong năm thứ ấy."],["夫道德仁義禮五者一體也","Phù đạo, đức, nhân, nghĩa, lễ, ngũ giả nhất thể dã.","Đạo, đức, nhân, nghĩa, lễ — năm thứ ấy là một thể, không tách rời nhau."],["凡事當留餘地得意不宜再往","Phàm sự đương lưu dư địa, đắc ý bất nghi tái vãng.","Việc gì cũng nên chừa lại một phần dư địa; lúc đắc ý không nên lấn tới thêm."],["宜未雨而綢繆毋臨渴而掘井","Nghi vị vũ nhi trù mâu, vô lâm khát nhi quật tỉnh.","Nên sửa soạn khi trời chưa mưa, đừng đợi khát mới đi đào giếng."],["居身務期質樸教子要有義方","Cư thân vụ kỳ chất phác, giáo tử yếu hữu nghĩa phương.","Ở đời cốt sao giữ mình mộc mạc chân thật; dạy con phải có phép tắc, có đạo lý rõ ràng."],["童僕勿用俊美妻妾切忌艶妝","Đồng bộc vật dụng tuấn mỹ, thê thiếp thiết kỵ diễm trang.","Người ở trong nhà đừng chọn kẻ tuấn tú bóng bẩy; vợ con chớ chuộng trang điểm lòe loẹt."],["自奉必須儉約宴客切勿留連","Tự phụng tất tu kiệm ước, yến khách thiết vật lưu liên.","Chi tiêu cho mình nhất định phải dè sẻn; đãi khách thì chớ kéo dài triền miên."],["莫貪意外之財莫飲過量之酒","Mạc tham ý ngoại chi tài, mạc ẩm quá lượng chi tửu.","Đừng tham của cải đến ngoài dự tính; đừng uống rượu quá sức mình."],["讀書志在聖賢為官心存君國","Độc thư chí tại thánh hiền, vi quan tâm tồn quân quốc.","Đọc sách thì chí hướng đặt ở bậc thánh hiền; làm quan thì lòng để nơi vua và nước."],["凡軍必知有五火之變以數守之","Phàm quân tất tri hữu ngũ hoả chi biến, dĩ số thủ chi.","Quân nào cũng phải biết năm biến chuyển của lửa, và theo quy luật mà phòng giữ."],["故將通於九變之利者知用兵矣","Cố tướng thông ư cửu biến chi lợi giả, tri dụng binh hĩ;","Tướng nào thông được cái lợi của chín điều biến hoá, là biết dùng binh;"],["務善策者無惡事無遠慮者有近憂","Vụ thiện sách giả vô ác sự, vô viễn lự giả hữu cận ưu.","Chăm lo kế sách tốt thì không có việc xấu xảy ra; không lo xa thì có buồn gần."],["德者人之所得使萬物各得其所欲","Đức giả, nhân chi sở đắc, sử vạn vật các đắc kỳ sở dục;","Đức là cái người ta có được, nó khiến muôn vật mỗi thứ đều được điều mình mong;"],["道者人之所蹈使萬物不知其所由","Đạo giả, nhân chi sở đạo, sử vạn vật bất tri kỳ sở do;","Đạo là con đường người ta bước đi, nó khiến muôn vật vận hành mà không biết vì sao mình đi theo lối ấy;"],["義者人之所宜賞善罰惡以立功立事","Nghĩa giả, nhân chi sở nghi, thưởng thiện phạt ác, dĩ lập công lập sự;","Nghĩa là điều người ta nên làm, thưởng kẻ tốt phạt kẻ xấu, để lập được công, làm được việc;"],["乖僻自是悔誤必多頽惰自甘家道難成","Quai tích tự thị, hối ngộ tất đa; đồi nọa tự cam, gia đạo nan thành.","Ngang ngược, cố chấp cho mình là đúng thì việc hối hận ắt nhiều; buông xuôi lười biếng mà tự bằng lòng thì nếp nhà khó dựng."],["任材使能所以濟務癉惡斥讒所以止亂","Nhiệm tài sử năng, sở dĩ tế vụ; đản ác xích sàm, sở dĩ chỉ loạn;","Giao việc cho người có tài, dùng người có năng lực là để việc xong; ghét kẻ ác, đuổi kẻ gièm pha là để ngăn loạn;"],["刻薄成家理無久享倫常乖舛立見消亡","Khắc bạc thành gia, lý vô cửu hưởng; luân thường quai suyễn, lập kiến tiêu vong.","Dựng cơ nghiệp bằng cách cay nghiệt bủn xỉn thì theo lẽ không hưởng được lâu; đạo cha con anh em mà trái ngược thì sớm thấy suy tàn."],["博學切問所以廣知高行微言所以修身","Bác học thiết vấn, sở dĩ quảng tri; cao hạnh vi ngôn, sở dĩ tu thân;","Học rộng, hỏi sát là để biết nhiều; làm việc cao, nói lời kín đáo là để sửa mình;"],["善欲人見不是真善惡恐人知便是大惡","Thiện dục nhân kiến, bất thị chân thiện; ác khủng nhân tri, tiện thị đại ác.","Làm điều thiện mà muốn người thấy thì chưa phải thiện thật; làm điều ác mà sợ người biết thì chính là ác lớn."],["夫戰勝攻取而不修其功者凶命曰費留","Phù chiến thắng công thủ, nhi bất tu kỳ công giả hung, mệnh viết phí lưu.","Đánh thắng, chiếm được, mà không củng cố thành quả là điều xấu, gọi là “phí lưu” — tốn công mà để đó."],["守分安命順時聽天為人若此庶乎近焉","Thủ phận an mệnh, thuận thời thính thiên; vi nhân nhược thử, thứ hồ cận yên.","Giữ đúng bổn phận, yên với số phận, thuận theo thời mà nghe mệnh trời; làm người được như thế thì có lẽ đã gần với đạo rồi."],["恭儉謙約所以自守深計遠慮所以不窮","Cung kiệm khiêm ước, sở dĩ tự thủ; thâm kế viễn lự, sở dĩ bất cùng;","Kính cẩn, tiết kiệm, nhún nhường, giản dị là để giữ mình; tính sâu, lo xa là để không bị dồn vào đường cùng;"],["推古驗今所以不惑先揆后度所以應卒","Suy cổ nghiệm kim, sở dĩ bất hoặc; tiên khuê hậu độ, sở dĩ ứng thốt;","Suy từ chuyện xưa để kiểm chuyện nay là để không mê lầm; trước đã lường, sau lại đo là để ứng được với việc bất ngờ;"],["禮者人之所履夙興夜寐以成人倫之序","Lễ giả, nhân chi sở lý, túc hưng dạ mị, dĩ thành nhân luân chi tự.","Lễ là điều người ta thực hành hằng ngày, dậy sớm ngủ muộn, để giữ cho trật tự giữa người với người được trọn."],["絕嗜禁欲所以除累抑非損惡所以禳過","Tuyệt thị cấm dục, sở dĩ trừ luỵ; ức phi tổn ác, sở dĩ nhương quá;","Dứt đam mê, ngăn ham muốn là để bỏ gánh nặng; nén điều sai, giảm điều xấu là để tránh lỗi lầm;"],["親仁友直所以扶顛近恕篤行所以接人","Thân nhân hữu trực, sở dĩ phù điên; cận thứ đốc hạnh, sở dĩ tiếp nhân;","Gần người nhân, bạn với người thẳng là để có chỗ đỡ khi vấp ngã; giữ lòng khoan dung, làm việc chắc chắn là để tiếp xúc với người;"],["設變致權所以解結括囊順會所以無咎","Thiết biến trí quyền, sở dĩ giải kết; quát nang thuận hội, sở dĩ vô cữu;","Đặt ra cách biến đổi, dùng tới quyền biến là để gỡ chỗ bế tắc; thắt miệng túi, thuận theo thời cơ là để không mắc lỗi;"],["貶酒闕色所以無污避嫌遠疑所以不誤","Biếm tửu khuyết sắc, sở dĩ vô ô; tị hiềm viễn nghi, sở dĩ bất ngộ;","Bớt rượu, kiềm sắc dục là để không vấy bẩn; tránh chỗ dễ bị nghi, xa việc đáng ngờ là để không lầm lỡ;"],["凡此五者將莫不聞知之者勝不知者不勝","Phàm thử ngũ giả, tướng mạc bất văn, tri chi giả thắng, bất tri giả bất thắng.","Năm điều ấy, tướng nào cũng từng nghe; ai hiểu thật thì thắng, ai không hiểu thì không thắng."],["孫子曰凡用兵之法將受命於君合軍聚眾","Tôn Tử viết: phàm dụng binh chi pháp, tướng thụ mệnh ư quân, hợp quân tụ chúng.","Tôn Tử nói: phép dùng binh, tướng nhận lệnh vua, họp quân tụ người."],["將者智信仁勇嚴也法者曲制官道主用也","Tướng giả, trí, tín, nhân, dũng, nghiêm dã. Pháp giả, khúc chế, quan đạo, chủ dụng dã.","Tướng là trí, tín, nhân, dũng, nghiêm. Pháp là cách tổ chức đội ngũ, cách đặt chức trách, cách quản lý vật lực."],["故上兵伐謀其次伐交其次伐兵其下攻城","Cố thượng binh phạt mưu, kỳ thứ phạt giao, kỳ thứ phạt binh, kỳ hạ công thành.","Vì vậy cách dùng binh cao nhất là đánh vào mưu kế của địch, kế đến là đánh vào quan hệ ngoại giao của địch, kế nữa là đánh quân địch, thấp nhất là đánh thành."],["三姑六婆實淫盜之媒婢美妾嬌非閨房之福","Tam cô lục bà, thực dâm đạo chi môi; tỳ mỹ thiếp kiều, phi khuê phòng chi phúc.","Hạng \"ba cô sáu bà\" lui tới cửa nhà thật là mối dẫn chuyện dâm ô, trộm cắp; nàng hầu đẹp, vợ lẽ nũng nịu không phải là phúc của buồng the."],["仁者人之所親有慈惠惻隱之心以遂其生成","Nhân giả, nhân chi sở thân, hữu từ huệ trắc ẩn chi tâm, dĩ toại kỳ sinh thành;","Nhân là điều khiến người ta gần nhau, có lòng thương, lòng ban ơn, lòng xót xa trước nỗi khổ, để giúp cho sự sống được thành;"],["兄弟叔侄須分多潤寡長幼內外宜法肅辭嚴","Huynh đệ thúc điệt, tu phân đa nhuận quả; trưởng ấu nội ngoại, nghi pháp túc từ nghiêm.","Anh em chú cháu, người có nhiều phải san bớt cho người có ít; lớn nhỏ trong ngoài, nên có phép tắc nghiêm, lời ăn tiếng nói đúng mực."],["勿恃勢力而陵逼孤寡毋貪口腹而恣殺生靈","Vật thị thế lực nhi lăng bức cô quả; vô tham khẩu phúc nhi tứ sát sinh linh.","Đừng cậy thế lực mà ức hiếp kẻ côi cút, góa bụa; đừng tham miệng ăn mà giết hại sinh vật bừa bãi."],["嫁女擇佳婿毋索重聘娶妻求淑女勿計厚奩","Giá nữ trạch giai tế, vô sách trọng sính; thú thê cầu thục nữ, vật kế hậu liêm.","Gả con gái thì chọn rể tốt, đừng đòi sính lễ nặng; cưới vợ thì tìm người hiền thục, đừng tính của hồi môn dày."],["居家戒爭訟訟則終凶處世戒多言言多必失","Cư gia giới tranh tụng, tụng tắc chung hung; xử thế giới đa ngôn, ngôn đa tất thất.","Trong nhà răn việc kiện tụng tranh giành, hễ kiện thì rốt cuộc xấu; ra đời răn việc nói nhiều, nói nhiều ắt lỡ lời."],["攻其無備出其不意此兵家之勝不可先傳也","Công kỳ vô bị, xuất kỳ bất ý. Thử binh gia chi thắng, bất khả tiên truyền dã.","Đánh vào chỗ địch không phòng bị, ra tay lúc địch không ngờ. Đó là cách thắng của nhà binh, không thể nói trước được."],["狎暱惡少久必受其累屈志老成急則可相依","Hiệp nật ác thiếu, cửu tất thụ kỳ lụy; khuất chí lão thành, cấp tắc khả tương y.","Suồng sã thân mật với đám thanh niên hư hỏng, lâu ngày ắt bị liên lụy; chịu nhún mình gần gũi người từng trải, khi gấp có thể nương nhờ."],["與肩挑貿易毋占便宜見窮苦親鄰須加溫卹","Dữ kiên thiêu mậu dịch, vô chiếm tiện nghi; kiến cùng khổ thân lân, tu gia ôn tuất.","Mua bán với người gánh hàng rong, đừng chiếm phần lợi về mình; thấy bà con hàng xóm nghèo khổ, phải thêm lòng ấm áp giúp đỡ."],["不可勝者守也可勝者攻也守則不足攻則有餘","Bất khả thắng giả, thủ dã; khả thắng giả, công dã. Thủ tắc bất túc, công tắc hữu dư.","Không thể bị thắng là nhờ phòng thủ; có thể thắng là nhờ tiến công. Giữ là khi sức chưa đủ; đánh là khi sức đã dư."],["夫將者國之輔也輔周則國必強輔隙則國必弱","Phù tướng giả, quốc chi phụ dã. Phụ chu tắc quốc tất cường, phụ khích tắc quốc tất nhược.","Tướng là người phụ tá của nước. Phụ tá chu toàn thì nước tất mạnh; phụ tá có kẽ hở thì nước tất yếu."],["一粥一飯當思來處不易半絲半縷恆念物力維艱","Nhất chúc nhất phạn, đương tư lai xứ bất dị; bán ti bán lũ, hằng niệm vật lực duy gian.","Một bát cháo, một bát cơm, nên nghĩ nó đến được đây không dễ; nửa sợi tơ, nửa sợi chỉ, hãy luôn nhớ của cải làm ra rất nhọc nhằn."],["人有喜慶不可生妒嫉心人有禍患不可生喜幸心","Nhân hữu hỉ khánh, bất khả sinh đố tật tâm; nhân hữu họa hoạn, bất khả sinh hỉ hạnh tâm.","Người ta có việc vui mừng, chớ sinh lòng ghen ghét; người ta gặp tai họa, chớ sinh lòng hả hê."],["器具質而潔瓦缶勝金玉飲食約而精園蔬愈珍饈","Khí cụ chất nhi khiết, ngõa phẫu thắng kim ngọc. Ẩm thực ước nhi tinh, viên sơ dũ trân tu.","Đồ dùng mộc mạc mà sạch sẽ thì vại sành hơn vàng ngọc. Ăn uống giản dị mà tinh thì rau vườn hơn sơn hào hải vị."],["圮地無舍衢地合交絕地無留圍地則謀死地則戰","Bĩ địa vô xá, cù địa hợp giao, tuyệt địa vô lưu, vi địa tắc mưu, tử địa tắc chiến.","Đất lở lội thì không đóng trại, đất ngã tư thì kết giao với láng giềng, đất cô lập thì không ở lâu, đất bị vây thì phải dùng mưu, đất chết thì phải đánh."],["是故屈諸侯者以害役諸侯者以業趨諸侯者以利","Thị cố khuất chư hầu giả dĩ hại, dịch chư hầu giả dĩ nghiệp, xu chư hầu giả dĩ lợi.","Vì vậy khiến các nước phải chịu khuất là nhờ cho họ thấy cái hại; khiến các nước phải bận rộn là nhờ giao cho họ việc; khiến các nước phải chạy theo là nhờ cho họ thấy lợi."],["祖宗雖遠祭祀不可不誠子孫雖愚經書不可不讀","Tổ tông tuy viễn, tế tự bất khả bất thành; tử tôn tuy ngu, kinh thư bất khả bất độc.","Tổ tiên dù đã xa, việc thờ cúng không thể không thành kính; con cháu dù tối dạ, sách vở không thể không cho đọc."],["聽婦言乖骨肉豈是丈夫重貲財薄父母不成人子","Thính phụ ngôn, quai cốt nhục, khởi thị trượng phu; trọng ti tài, bạc phụ mẫu, bất thành nhân tử.","Nghe lời bên gối mà xa lìa ruột thịt, sao gọi là bậc trượng phu; coi trọng tiền của mà bạc bẽo với cha mẹ, không đáng làm con."],["見色而起淫心報在妻女匿怨而用暗箭禍延子孫","Kiến sắc nhi khởi dâm tâm, báo tại thê nữ; nặc oán nhi dụng ám tiễn, họa diên tử tôn.","Thấy sắc đẹp mà nổi lòng tà dâm thì quả báo rơi vào vợ con; giấu oán hận mà bắn tên ngầm thì tai họa kéo đến đời con cháu."],["計利以聽乃為之勢以佐其外勢者因利而制權也","Kế lợi dĩ thính, nãi vi chi thế, dĩ tá kỳ ngoại. Thế giả, nhân lợi nhi chế quyền dã.","Kế đã tính ra lợi và được nghe theo, thì tạo thế để giúp việc bên ngoài. Thế là dựa vào chỗ lợi mà nắm quyền chủ động."],["賞不服人罰不甘心者叛賞及無功罰及無罪者酷","Thưởng bất phục nhân, phạt bất cam tâm giả bạn, thưởng cập vô công, phạt cập vô tội giả khốc.","Thưởng mà người không phục, phạt mà người không cam lòng thì sinh phản; thưởng đến kẻ không có công, phạt đến kẻ không có tội là tàn khốc."],["如此理身理家理國可也右第六章言安而履之謂禮","Như thử, lý thân, lý gia, lý quốc, khả dã. Hữu đệ lục chương, ngôn an nhi lý chi vị lễ.","Được như vậy thì sửa mình, sửa nhà, sửa nước đều có thể. Trên đây là chương sáu, nói rằng yên ổn mà thực hành được gọi là lễ."],["將聽吾計用之必勝留之將不聽吾計用之必敗去之","Tướng thính ngô kế, dụng chi tất thắng, lưu chi; tướng bất thính ngô kế, dụng chi tất bại, khứ chi.","Tướng nghe theo kế của ta, dùng thì tất thắng, hãy giữ lại; tướng không nghe kế của ta, dùng thì tất bại, hãy cho đi."],["故以火佐攻者明以水佐攻者強水可以絕不可以奪","Cố dĩ hoả tá công giả minh, dĩ thuỷ tá công giả cường. Thuỷ khả dĩ tuyệt, bất khả dĩ đoạt.","Dùng lửa giúp cho việc đánh là sáng suốt; dùng nước giúp cho việc đánh là mạnh mẽ. Nước có thể cắt đứt địch, nhưng không thể cướp lấy của địch."],["道者令民與上同意可與之死可與之生而不畏危也","Đạo giả, lệnh dân dữ thượng đồng ý, khả dữ chi tử, khả dữ chi sinh, nhi bất uý nguy dã.","Đạo là làm cho dân cùng một lòng với người trên, có thể cùng chết, có thể cùng sống với họ mà không sợ nguy."],["天者陰陽寒暑時制也地者高下遠近險易廣狹死生也","Thiên giả, âm dương, hàn thử, thời chế dã. Địa giả, cao hạ, viễn cận, hiểm dị, quảng hiệp, tử sinh dã.","Trời là ngày đêm, nóng lạnh, mùa tiết. Đất là cao thấp, xa gần, hiểm trở hay bằng phẳng, rộng hay hẹp, chỗ chết hay chỗ sống."],["孫子曰兵者國之大事死生之地存亡之道不可不察也","Tôn Tử viết: binh giả, quốc chi đại sự, tử sinh chi địa, tồn vong chi đạo, bất khả bất sát dã.","Tôn Tử nói: việc binh là việc lớn của nước, là chỗ quyết định sống chết, là con đường còn hay mất, không thể không xét kỹ."],["孫子曰凡治衆如治寡分數是也鬥衆如鬥寡形名是也","Tôn Tử viết: phàm trị chúng như trị quả, phân số thị dã; đấu chúng như đấu quả, hình danh thị dã;","Tôn Tử nói: cai quản số đông như cai quản số ít, là nhờ chia tổ chức thành đơn vị; điều khiển số đông chiến đấu như điều khiển số ít, là nhờ cờ hiệu và hiệu lệnh;"],["故形兵之極至於無形無形則深間不能窺智者不能謀","Cố hình binh chi cực, chí ư vô hình. Vô hình, tắc thâm gián bất năng khuy, trí giả bất năng mưu.","Cho nên bày binh đến mức cao nhất là không còn hình. Không hình thì gián điệp len sâu cũng không dò được, người khôn cũng không bày được kế."],["故曰明主慮之良將修之非利不動非得不用非危不戰","Cố viết: minh chủ lự chi, lương tướng tu chi, phi lợi bất động, phi đắc bất dụng, phi nguy bất chiến.","Nên nói: vua sáng phải lo tính điều này, tướng tốt phải chăm lo điều này; không có lợi thì không động, không được gì thì không dùng quân, không gặp nguy thì không đánh."],["故舉秋毫不為多力見日月不為明目聞雷霆不為聰耳","Cố cử thu hào bất vi đa lực, kiến nhật nguyệt bất vi minh mục, văn lôi đình bất vi thông nhĩ.","Nhấc một sợi lông mùa thu không gọi là khoẻ; thấy mặt trời mặt trăng không gọi là mắt sáng; nghe tiếng sấm không gọi là tai tinh."],["見富貴而生諂容者最可恥遇貧窮而作驕態者賤莫甚","Kiến phú quý nhi sinh siểm dung giả, tối khả sỉ, ngộ bần cùng nhi tác kiêu thái giả, tiện mạc thậm.","Thấy kẻ giàu sang mà lộ vẻ nịnh bợ là đáng hổ thẹn nhất; gặp người nghèo khó mà làm bộ kiêu căng là hèn không gì bằng."],["進而不可禦者沖其虛也退而不可追者速而不可及也","Tiến nhi bất khả ngự giả, xung kỳ hư dã; thoái nhi bất khả truy giả, tốc nhi bất khả cập dã.","Tiến mà địch không chống được là vì xông vào chỗ trống của họ; lui mà địch không đuổi được là vì nhanh đến mức họ không theo kịp."],["五間之事主必知之知之必在於反間故反間不可不厚也","Ngũ gián chi sự, chủ tất tri chi, tri chi tất tại ư phản gián, cố phản gián bất khả bất hậu dã.","Việc của năm loại gián điệp, vua phải nắm rõ; mà nắm được là nhờ gián điệp phản lại, nên gián điệp phản lại không thể không được đãi hậu."],["微乎微乎至于無形神乎神乎至于無聲故能為敵之司命","Vi hồ vi hồ! Chí vu vô hình; thần hồ thần hồ! Chí vu vô thanh, cố năng vi địch chi tư mệnh.","Tinh vi thay, tinh vi thay, đến mức không còn hình; thần diệu thay, thần diệu thay, đến mức không còn tiếng; nhờ vậy nắm được sinh mệnh của địch."],["故兵貴勝不貴久故知兵之將民之司命國家安危之主也","Cố binh quý thắng, bất quý cửu. Cố tri binh chi tướng, dân chi tư mệnh, quốc gia an nguy chi chủ dã.","Vì vậy việc binh quý ở thắng, không quý ở kéo dài. Vị tướng hiểu việc binh là người nắm sinh mệnh của dân, là chủ của sự yên nguy của nước."],["故迂其途而誘之以利後人發先人至此知迂直之計者也","Cố vu kỳ đồ, nhi dụ chi dĩ lợi, hậu nhân phát, tiên nhân chí, thử tri vu trực chi kế giả dã.","Vì vậy đi đường vòng mà dụ địch bằng lợi, xuất phát sau người nhưng đến trước người — đó là hiểu kế vòng và thẳng."],["若時至而行則能極人臣之位得機而動則能成絕代之功","Nhược thời chí nhi hành, tắc năng cực nhân thần chi vị; đắc cơ nhi động, tắc năng thành tuyệt đại chi công.","Thời đến mà hành động thì có thể lên tới địa vị cao nhất của kẻ làm tôi; gặp cơ hội mà ra tay thì có thể làm nên công lớn hiếm có."],["令與心乖者廢后令謬前者毀怒而無威者犯好直辱人者殃","Lệnh dữ tâm quai giả phế, hậu lệnh mậu tiền giả huỷ, nộ nhi vô uy giả phạm, hiếu trực nhục nhân giả ương,","Lệnh trái với lòng người là lệnh bị bỏ; lệnh sau mâu thuẫn với lệnh trước là tự phá; nổi giận mà không có uy thì bị lấn; ưa nói thẳng đến mức làm nhục người thì gặp tai ương;"],["以明示下者暗有過不知者弊迷而不返者惑以言取怨者禍","Dĩ minh thị hạ giả ám, hữu quá bất tri giả tệ, mê nhi bất phản giả hoặc, dĩ ngôn thủ oán giả hoạ,","Khoe cái sáng của mình với người dưới là tối; có lỗi mà không biết là hỏng; lầm đường mà không quay lại là mê; vì lời nói mà chuốc oán là hoạ;"],["戮辱所任者危慢其所敬者兇貌合心離者孤親讒遠忠者亡","Lục nhục sở nhiệm giả nguy, mạn kỳ sở kính giả hung, mạo hợp tâm ly giả cô, thân sàm viễn trung giả vong,","Làm nhục người mình đã giao việc là nguy; khinh người mình vốn phải kính là xấu; ngoài mặt hoà mà trong lòng xa nhau là cô độc; gần kẻ gièm pha, xa người trung thực là tiêu vong;"],["是故百戰百勝非善之善者也不戰而屈人之兵善之善者也","Thị cố bách chiến bách thắng, phi thiện chi thiện giả dã; bất chiến nhi khuất nhân chi binh, thiện chi thiện giả dã.","Vì vậy trăm trận trăm thắng chưa phải là giỏi nhất; không đánh mà khiến quân địch phải chịu khuất mới là giỏi nhất."],["其用戰也貴勝久則鈍兵挫銳攻城則力屈久暴師則國用不足","Kỳ dụng chiến dã, quý thắng, cửu tắc độn binh tỏa nhuệ, công thành tắc lực khuất, cửu bộc sư tắc quốc dụng bất túc.","Đã đánh thì cốt thắng nhanh; kéo dài thì quân cùn nhụt khí, đánh thành thì hao sức, để quân ở ngoài lâu thì của nước không đủ."],["失其所強者弱決策于不仁者險陰計外泄者敗厚斂薄施者凋","Thất kỳ sở cường giả nhược, quyết sách vu bất nhân giả hiểm, âm kế ngoại tiết giả bại, hậu liễm bạc thi giả điêu.","Để mất cái mình vốn mạnh thì thành yếu; hỏi kế sách ở kẻ bất nhân thì nguy hiểm; mưu kín mà lọt ra ngoài thì thất bại; thu vào nhiều mà cho ra ít thì héo tàn."],["微哉微哉無所不用間也間事未發而先聞者間與所告者皆死","Vi tai! Vi tai! Vô sở bất dụng gián dã. Gián sự vị phát nhi tiên văn giả, gián dữ sở cáo giả giai tử.","Tinh vi thay! Tinh vi thay! Không việc gì là không dùng đến gián điệp. Việc gián điệp chưa tiến hành mà đã lọt ra ngoài, thì gián điệp và người được nghe đều phải chết."],["故善動敵者形之敵必從之予之敵必取之以利動之以卒待之","Cố thiện động địch giả, hình chi, địch tất tòng chi; dữ chi, địch tất thủ chi. Dĩ lợi động chi, dĩ tốt đãi chi.","Người giỏi điều động địch thì bày ra hình, địch tất theo; đưa ra mồi, địch tất lấy. Dùng lợi để kéo địch động, dùng quân đã sẵn để đón."],["故智將務食於敵食敵一鍾當吾二十鍾萁稈一石當吾二十石","Cố trí tướng vụ thực ư địch, thực địch nhất chung, đương ngô nhị thập chung; ky cán nhất thạch, đương ngô nhị thập thạch.","Vì vậy tướng khôn cốt lấy lương ăn tại đất địch: ăn một chung lương của địch bằng hai mươi chung của mình; một thạch cỏ rơm của địch bằng hai mươi thạch của mình."],["凡此五者將之過也用兵之災也覆軍殺將必以五危不可不察也","Phàm thử ngũ giả, tướng chi quá dã, dụng binh chi tai dã. Phúc quân sát tướng, tất dĩ ngũ nguy, bất khả bất sát dã.","Năm điều ấy là lỗi của tướng, là tai hoạ của việc binh. Quân tan tướng chết, tất do năm điều nguy ấy, không thể không xét kỹ."],["善守者藏於九地之下善攻者動於九天之上故能自保而全勝也","Thiện thủ giả, tàng ư cửu địa chi hạ; thiện công giả, động ư cửu thiên chi thượng, cố năng tự bảo nhi toàn thắng dã.","Người giỏi giữ thì ẩn sâu như dưới chín lớp đất; người giỏi đánh thì động như trên chín tầng trời; nhờ vậy giữ được mình mà thắng trọn."],["善用兵者役不再籍糧不三載取用於國因糧於敵故軍食可足也","Thiện dụng binh giả, dịch bất tái tịch, lương bất tam tái; thủ dụng ư quốc, nhân lương ư địch, cố quân thực khả túc dã.","Người giỏi dùng binh không bắt lính đến lần thứ hai, không chở lương đến lần thứ ba; khí giới lấy từ trong nước, lương thực lấy tại đất địch, nên quân đủ ăn."],["孫子曰凡處軍相敵絕山依谷視生處高戰隆無登此處山之軍也","Tôn Tử viết: phàm xử quân tương địch, tuyệt sơn y cốc, thị sinh xử cao, chiến long vô đăng, thử xử sơn chi quân dã.","Tôn Tử nói: về việc đóng quân và xem xét địch: vượt núi thì men theo khe, chọn nơi sáng sủa mà ở chỗ cao, địch ở trên cao thì không đánh ngược lên — đó là cách đóng quân ở núi."],["家門和順雖饔飧不繼亦有餘歡國課早完即囊橐無餘自得至樂","Gia môn hòa thuận, tuy ung sôn bất kế, diệc hữu dư hoan; quốc khóa tảo hoàn, tức nang thác vô dư, tự đắc chí lạc.","Cửa nhà hòa thuận thì dù bữa sáng bữa tối có khi đứt đoạn vẫn thừa niềm vui; thuế nước nộp sớm xong thì dù túi không còn dư vẫn tự thấy vui sướng tột cùng."],["必索敵人之間來間我者因而利之導而舍之故反間可得而用也","Tất sách địch nhân chi gián lai gián ngã giả, nhân nhi lợi chi, đạo nhi xá chi, cố phản gián khả đắc nhi dụng dã;","Phải tìm ra gián điệp của địch đến dò xét ta, nhân đó mà mua chuộc, dẫn dắt rồi cho ở lại, nhờ vậy mà có được gián điệp phản lại để dùng;"],["掠鄉分衆廓地分利懸權而動先知迂直之計者勝此軍爭之法也","Lược hương phân chúng, khuếch địa phân lợi, huyền quyền nhi động. Tiên tri vu trực chi kế giả thắng, thử quân tranh chi pháp dã.","Lấy được làng thì chia cho quân, mở được đất thì chia lợi, cân nhắc lợi hại rồi mới động. Ai biết trước kế vòng và thẳng thì thắng — đó là phép tranh lợi thế."],["故善戰者能為不可勝不能使敵之必可勝故曰勝可知而不可為","Cố thiện chiến giả, năng vi bất khả thắng, bất năng sử địch chi tất khả thắng. Cố viết: thắng khả tri, nhi bất khả vi.","Vì vậy người giỏi đánh có thể làm cho mình không bị thắng, nhưng không thể bắt địch nhất định phải thua. Nên nói: thắng có thể biết trước, nhưng không thể ép ra được."],["故軍爭為利軍爭為危舉軍而爭利則不及委軍而爭利則輜重捐","Cố quân tranh vi lợi, quân tranh vi nguy. Cử quân nhi tranh lợi, tắc bất cập; uỷ quân nhi tranh lợi, tắc truy trọng quyên.","Tranh lợi thế vừa là lợi, vừa là nguy. Đem cả quân đi tranh lợi thì chậm, không kịp; bỏ bớt quân để tranh lợi thì mất xe lương."],["途有所不由軍有所不擊城有所不攻地有所不爭君命有所不受","Đồ hữu sở bất do, quân hữu sở bất kích, thành hữu sở bất công, địa hữu sở bất tranh, quân mệnh hữu sở bất thụ.","Có đường không nên đi, có quân không nên đánh, có thành không nên công, có đất không nên tranh, có lệnh vua không nên nhận."],["險形者我先居之必居高陽以待敵若敵先居之引而去之勿從也","Hiểm hình giả, ngã tiên cư chi, tất cư cao dương dĩ đãi địch; nhược địch tiên cư chi, dẫn nhi khứ chi, vật tòng dã.","Đất hiểm, nếu ta chiếm trước thì phải đóng ở chỗ cao sáng mà chờ địch; nếu địch đã chiếm trước thì rút đi, đừng theo."],["黎明即起灑掃庭除要內外整潔既昏便息關鎖門戶必親自檢點","Lê minh tức khởi, sái tảo đình trừ, yếu nội ngoại chỉnh khiết. Ký hôn tiện tức, quan tỏa môn hộ, tất thân tự kiểm điểm.","Tảng sáng thì dậy ngay, rưới nước quét sân quét thềm, trong ngoài phải gọn gàng sạch sẽ. Tối đến thì nghỉ, đóng cửa cài then, nhất thiết tự mình đi xem lại một lượt."],["主不可以怒而興師將不可以慍而致戰合於利而動不合於利而止","Chủ bất khả dĩ nộ nhi hưng sư, tướng bất khả dĩ uấn nhi trí chiến. Hợp ư lợi nhi động, bất hợp ư lợi nhi chỉ.","Vua không được vì giận mà dấy quân, tướng không được vì bực mà gây chiến. Hợp với lợi thì động, không hợp với lợi thì dừng."],["夫鈍兵挫銳屈力殫貨則諸侯乘其弊而起雖有智者不能善其後矣","Phù độn binh tỏa nhuệ, khuất lực đàn hoá, tắc chư hầu thừa kỳ tệ nhi khởi, tuy hữu trí giả, bất năng thiện kỳ hậu hĩ.","Quân cùn khí nhụt, sức kiệt của hết, thì các nước khác nhân lúc suy yếu mà nổi lên; bấy giờ dù có người khôn cũng không cứu được hậu quả."],["是故智者之慮必雜於利害雜於利而務可信也雜於害而患可解也","Thị cố trí giả chi lự, tất tạp ư lợi hại, tạp ư lợi nhi vụ khả tín dã, tạp ư hại nhi hoạn khả giải dã.","Vì vậy người khôn khi suy tính tất xét cả lợi lẫn hại: trong cái lợi mà nghĩ đến hại thì việc mới chắc; trong cái hại mà nghĩ đến lợi thì hoạn nạn mới gỡ được."],["橛橛梗梗所以立功孜孜淑淑所以保終右第三章言志不可以妄求","Quyết quyết cánh cánh, sở dĩ lập công; tư tư thục thục, sở dĩ bảo chung. Hữu đệ tam chương, ngôn chí bất khả dĩ vọng cầu.","Vững vàng cứng cỏi là để lập công; chăm chỉ và lành thiện không ngơi là để giữ được trọn vẹn đến cuối. Trên đây là chương ba, nói rằng chí hướng không thể cầu bừa."],["火可發於外無待於內以時發之火發上風無攻下風晝風久夜風止","Hoả khả phát ư ngoại, vô đãi ư nội, dĩ thời phát chi; hoả phát thượng phong, vô công hạ phong; trú phong cửu, dạ phong chỉ.","Lửa có thể phát từ bên ngoài thì không cần chờ bên trong, cứ đúng lúc mà phát; lửa phát ở đầu gió thì đừng đánh từ cuối gió; gió ban ngày thổi lâu, gió ban đêm thường ngừng."],["略己而責人者不治自厚而薄人者棄以過棄功者損群下外異者淪","Lược kỷ nhi trách nhân giả bất trị, tự hậu nhi bạc nhân giả khí, dĩ quá khí công giả tổn, quần hạ ngoại dị giả luân,","Dễ với mình mà khắt khe với người thì không cai quản được; hậu với mình mà bạc với người thì bị bỏ rơi; vì một lỗi mà xoá hết công thì tổn thất; người dưới ngoài mặt theo mà trong lòng khác thì chìm đắm;"],["隘形者我先居之必盈之以待敵若敵先居之盈而勿從不盈而從之","Ải hình giả, ngã tiên cư chi, tất doanh chi dĩ đãi địch. Nhược địch tiên cư chi, doanh nhi vật tòng, bất doanh nhi tòng chi.","Đất hẹp, nếu ta chiếm trước thì phải bố trí quân đầy khắp cửa hẹp mà chờ địch. Nếu địch chiếm trước, họ đã đóng đầy thì đừng theo vào; chưa đóng đầy thì có thể theo vào."],["兵者詭道也故能而示之不能用而示之不用近而示之遠遠而示之近","Binh giả, quỷ đạo dã. Cố năng nhi thị chi bất năng, dụng nhi thị chi bất dụng, cận nhi thị chi viễn, viễn nhi thị chi cận.","Việc binh là đường lối biến hoá khó lường. Nên có khả năng thì tỏ ra không có, định dùng thì tỏ ra không dùng, ở gần thì tỏ ra xa, ở xa thì tỏ ra gần."],["孫子曰凡火攻有五一曰火人二曰火積三曰火輜四曰火庫五曰火隊","Tôn Tử viết: phàm hoả công hữu ngũ: nhất viết hoả nhân, nhị viết hoả tích, tam viết hoả truy, tứ viết hoả khố, ngũ viết hoả đội.","Tôn Tử nói: đánh bằng lửa có năm cách: một là đốt người, hai là đốt lương tích trữ, ba là đốt xe chở, bốn là đốt kho, năm là đốt đội hình."],["孫子曰昔之善戰者先為不可勝以待敵之可勝不可勝在己可勝在敵","Tôn Tử viết: tích chi thiện chiến giả, tiên vi bất khả thắng, dĩ đãi địch chi khả thắng. Bất khả thắng tại kỷ, khả thắng tại địch.","Tôn Tử nói: người giỏi đánh thời xưa trước hết làm cho mình không thể bị thắng, rồi chờ lúc địch có thể bị thắng. Không thể bị thắng là ở mình; có thể thắng được địch là ở địch."],["愛人深者求賢急樂得賢者養人厚國將霸者士皆歸邦將亡者賢先避","Ái nhân thâm giả cầu hiền cấp, lạc đắc hiền giả dưỡng nhân hậu. Quốc tương bá giả sĩ giai quy, bang tương vong giả hiền tiên tị.","Người thương dân sâu thì gấp gáp tìm người tài; người vui vì được người tài thì nuôi họ hậu hĩnh. Nước sắp mạnh thì kẻ sĩ đều kéo về; nước sắp mất thì người hiền bỏ đi trước."],["故為兵之事在於佯順敵之意併敵一向千里殺將是謂巧能成事者也","Cố vi binh chi sự, tại ư dương thuận địch chi ý, tính địch nhất hướng, thiên lý sát tướng, thị vị xảo năng thành sự giả dã.","Việc binh cốt ở chỗ giả như thuận theo ý địch, rồi dồn sức về một hướng vào địch, đi nghìn dặm mà giết được tướng — thế gọi là khéo mà thành việc."],["見勝不過衆人之所知非善之善者也戰勝而天下曰善非善之善者也","Kiến thắng bất quá chúng nhân chi sở tri, phi thiện chi thiện giả dã; chiến thắng nhi thiên hạ viết thiện, phi thiện chi thiện giả dã.","Thấy được cái thắng mà ai cũng thấy, chưa phải giỏi nhất; đánh thắng mà thiên hạ khen giỏi, cũng chưa phải giỏi nhất."],["令發之日士卒坐者涕沾襟偃臥者淚交頤投之無所往者則諸劌之勇也","Lệnh phát chi nhật, sĩ tốt toạ giả thế triêm khâm, yển ngoạ giả lệ giao di. Đầu chi vô sở vãng giả, tắc Chư, Quế chi dũng dã.","Ngày ban lệnh xuất quân, binh sĩ ngồi thì nước mắt thấm áo, nằm thì lệ chảy ròng má. Nhưng đặt họ vào chỗ không còn đường đi, họ sẽ dũng cảm như Chuyên Chư, như Tào Quế."],["故用兵之法無恃其不來恃吾有以待之無恃其不攻恃吾有所不可攻也","Cố dụng binh chi pháp, vô thị kỳ bất lai, thị ngô hữu dĩ đãi chi; vô thị kỳ bất công, thị ngô hữu sở bất khả công dã.","Phép dùng binh: không cậy vào việc địch không đến, mà cậy vào việc ta đã có cách đón; không cậy vào việc địch không đánh, mà cậy vào việc ta có chỗ không thể bị đánh."],["行足以為儀表智足以決嫌疑信足以使守約廉足以使分財此人之豪也","Hạnh túc dĩ vi nghi biểu, trí túc dĩ quyết hiềm nghi, tín túc dĩ sử thủ ước, liêm túc dĩ sử phân tài, thử nhân chi hào dã.","Nết đủ để làm mẫu cho người khác, trí đủ để phân xử chỗ ngờ vực, lòng tin đủ để khiến người giữ lời hứa, trong sạch đủ để được giao chia của — đó là bậc hào kiệt."],["以吾度之越人之兵雖多亦奚益於勝敗哉故曰勝可擅也敵雖衆可使無鬥","Dĩ ngô độ chi, Việt nhân chi binh tuy đa, diệc hề ích ư thắng bại tai! Cố viết: thắng khả thiện dã. Địch tuy chúng, khả sử vô đấu.","Theo ta xét, quân nước Việt dù đông, có ích gì cho việc thắng bại! Nên nói: thắng là có thể tự nắm lấy. Địch dù đông, có thể làm cho không đánh được."],["德足以懷遠信足以一異義足以得眾才足以鑒古明足以照下此人之俊也","Đức túc dĩ hoài viễn, tín túc dĩ nhất dị, nghĩa túc dĩ đắc chúng, tài túc dĩ giám cổ, minh túc dĩ chiếu hạ, thử nhân chi tuấn dã.","Đức đủ để thu phục người ở xa, lòng tin đủ để hợp nhất những kẻ khác nhau, nghĩa đủ để được đông người theo, tài đủ để soi xét chuyện xưa, sáng suốt đủ để nhìn rõ người dưới — đó là bậc tuấn kiệt."],["戰勢不過奇正奇正之變不可勝窮也奇正相生如循環之無端孰能窮之哉","Chiến thế bất quá kỳ chính, kỳ chính chi biến, bất khả thắng cùng dã. Kỳ chính tương sinh, như tuần hoàn chi vô đoan, thục năng cùng chi tai?","Thế trận chỉ có kỳ và chính, nhưng kỳ chính biến hoá thì không ai dò hết. Kỳ và chính sinh ra nhau như vòng tròn không đầu không cuối, ai mà dò hết được?"],["故善戰者求之於勢不責於人故能擇人而任勢任勢者其戰人也如轉木石","Cố thiện chiến giả, cầu chi ư thế, bất trách ư nhân, cố năng trạch nhân nhi nhiệm thế. Nhiệm thế giả, kỳ chiến nhân dã, như chuyển mộc thạch.","Vì vậy người giỏi đánh tìm thắng ở thế, không đòi hỏi ở từng người, nên biết chọn người rồi giao họ vào thế. Người biết dùng thế thì điều khiển quân như lăn gỗ lăn đá."],["故將有五危必死可殺也必生可虜也忿速可侮也廉潔可辱也愛民可煩也","Cố tướng hữu ngũ nguy: tất tử, khả sát dã; tất sinh, khả lỗ dã; phẫn tốc, khả vũ dã; liêm khiết, khả nhục dã; ái dân, khả phiền dã.","Tướng có năm điều nguy: liều chết thì có thể bị giết; ham sống thì có thể bị bắt; nóng vội thì có thể bị khích; quá trọng danh tiết thì có thể bị làm nhục mà mất khôn; quá thương dân thì có thể bị làm cho rối."],["故曰知彼知己百戰不殆不知彼而知己一勝一負不知彼不知己每戰必殆","Cố viết: tri bỉ tri kỷ, bách chiến bất đãi; bất tri bỉ nhi tri kỷ, nhất thắng nhất phụ; bất tri bỉ bất tri kỷ, mỗi chiến tất đãi.","Vì vậy nói: biết người biết mình, trăm trận không nguy; không biết người mà biết mình, thắng thua ngang nhau; không biết người cũng không biết mình, trận nào cũng nguy."],["故知兵者動而不迷舉而不窮故曰知彼知己勝乃不殆知天知地勝乃可全","Cố tri binh giả, động nhi bất mê, cử nhi bất cùng. Cố viết: tri bỉ tri kỷ, thắng nãi bất đãi; tri thiên tri địa, thắng nãi khả toàn.","Vì vậy người hiểu việc binh động mà không mê lầm, làm mà không bế tắc. Nên nói: biết người biết mình, thắng mới không nguy; biết trời biết đất, thắng mới trọn vẹn."],["故經之以五事校之以七計而索其情一曰道二曰天三曰地四曰將五曰法","Cố kinh chi dĩ ngũ sự, giảo chi dĩ thất kế, nhi sách kỳ tình: nhất viết đạo, nhị viết thiên, tam viết địa, tứ viết tướng, ngũ viết pháp.","Vì vậy phải xem xét bằng năm việc, so sánh bằng bảy điều, để tìm ra thực tình: một là đạo, hai là trời, ba là đất, bốn là tướng, năm là pháp."],["明莫明于體物吉莫吉于知足苦莫苦于多愿悲莫悲于精散病莫病于無常","Minh mạc minh vu thể vật; cát mạc cát vu tri túc, khổ mạc khổ vu đa nguyện, bi mạc bi vu tinh tán, bệnh mạc bệnh vu vô thường,","Không gì sáng bằng thấu hiểu sự vật; không gì lành bằng biết đủ, không gì khổ bằng mong muốn quá nhiều, không gì buồn bằng tinh thần tán loạn, không gì bệnh bằng sống không có nếp;"],["牧人以德者集繩人以刑者散小功不賞則大功不立小怨不赦則大怨必生","Mục nhân dĩ đức giả tập, thằng nhân dĩ hình giả tán. Tiểu công bất thưởng, tắc đại công bất lập, tiểu oán bất xá, tắc đại oán tất sinh.","Dẫn dắt người bằng đức thì người tụ lại, trói buộc người bằng hình phạt thì người tan đi. Công nhỏ không thưởng thì công lớn không thành; oán nhỏ không bỏ qua thì oán lớn tất sinh."],["自疑不信人自信不疑人枉士無直友曲上無直下危國無賢人亂政無善人","Tự nghi bất tín nhân, tự tín bất nghi nhân. Uổng sĩ vô trực hữu, khúc thượng vô trực hạ, nguy quốc vô hiền nhân, loạn chính vô thiện nhân.","Tự ngờ mình thì không tin được người; tự tin ở mình thì không ngờ người. Kẻ cong queo không có bạn thẳng; người trên cong thì người dưới không thẳng; nước nguy không còn người hiền; chính sự loạn không còn người tốt."],["足寒傷心人怨傷國山將崩者下先隳國將衰者人先弊根枯枝朽人困國殘","Túc hàn thương tâm, nhân oán thương quốc, sơn tương băng giả hạ tiên huy, quốc tương suy giả nhân tiên tệ. Căn khô chi hủ, nhân khốn quốc tàn.","Chân lạnh thì hại đến tim; dân oán thì hại đến nước. Núi sắp sụp thì chân núi lở trước; nước sắp suy thì dân mỏi mệt trước. Gốc khô thì cành mục; dân khốn thì nước tàn."],["近色遠賢者惛女謁公行者亂私人以官者浮凌下取勝者侵名不勝實者耗","Cận sắc viễn hiền giả hôn, nữ yết công hành giả loạn, tư nhân dĩ quan giả phù, lăng hạ thủ thắng giả xâm, danh bất thắng thực giả hao,","Gần sắc đẹp, xa người hiền là u mê; để chuyện cầu cạnh qua cửa sau diễn ra công khai là loạn; đem chức quan ban cho người riêng của mình là nền tảng bấp bênh; ép người dưới để giành phần thắng là xâm hại; danh không xứng với thực là hao tổn;"],["遠形者勢均難以挑戰戰而不利凡此六者地之道也將之至任不可不察也","Viễn hình giả, thế quân, nan dĩ khiêu chiến, chiến nhi bất lợi. Phàm thử lục giả, địa chi đạo dã, tướng chi chí nhiệm, bất khả bất sát dã.","Đất xa, hai bên thế ngang nhau, khó mà khiêu chiến, đánh thì bất lợi. Sáu loại đất ấy là lẽ của địa hình, là trách nhiệm lớn nhất của tướng, không thể không xét kỹ."],["釋己而教人者逆正己而化人者順逆者難從順者易行難從則亂易行則理","Thích kỷ nhi giáo nhân giả nghịch, chính kỷ nhi hoá nhân giả thuận, nghịch giả nan tòng, thuận giả dị hành, nan tòng tắc loạn, dị hành tắc lý.","Buông lơi mình mà đi dạy người là ngược; sửa mình trước rồi cảm hoá người là thuận. Ngược thì người khó theo, thuận thì người dễ làm; khó theo thì loạn, dễ làm thì nên nếp."],["三軍之衆可使必受敵而無敗者奇正是也兵之所加如以碫投卵者虛實是也","Tam quân chi chúng, khả sử tất thụ địch nhi vô bại giả, kỳ chính thị dã; binh chi sở gia, như dĩ đoán đầu noãn giả, hư thực thị dã.","Cả ba quân đón địch mà không thua, là nhờ biết dùng chính binh và kỳ binh; quân đánh vào đâu như lấy đá ném trứng, là nhờ biết chỗ trống chỗ đặc."],["令素行以教其民則民服令素不行以教其民則民不服令素行者與衆相得也","Lệnh tố hành dĩ giáo kỳ dân, tắc dân phục; lệnh tố bất hành dĩ giáo kỳ dân, tắc dân bất phục. Lệnh tố hành giả, dữ chúng tương đắc dã.","Lệnh vốn luôn được thi hành nghiêm thì khi dạy dân, dân phục; lệnh vốn không được thi hành thì khi dạy dân, dân không phục. Lệnh luôn được thi hành là vì người trên và người dưới hợp lòng nhau."],["可以往難以返曰掛掛形者敵無備出而勝之敵若有備出而不勝難以返不利","Khả dĩ vãng, nan dĩ phản, viết quải. Quải hình giả, địch vô bị, xuất nhi thắng chi; địch nhược hữu bị, xuất nhi bất thắng, nan dĩ phản, bất lợi.","Đến được mà khó về, gọi là đất treo. Ở đất treo, địch không phòng bị thì ra đánh mà thắng; địch đã phòng bị thì ra đánh không thắng, mà về cũng khó — bất lợi."],["如其不遇沒身而已是以其道足高而名重于后代右第一章言道不可以無始","Như kỳ bất ngộ, một thân nhi dĩ. Thị dĩ kỳ đạo túc cao, nhi danh trọng vu hậu đại. Hữu đệ nhất chương, ngôn đạo bất khả dĩ vô thủy.","Nếu không gặp thời thì lặng lẽ sống hết đời mình, thế thôi. Nhờ vậy đạo của họ đủ cao, mà tên tuổi được đời sau coi trọng. Trên đây là chương một, nói rằng đạo không thể không có khởi đầu."],["既用不任者疏行賞吝色者沮多許少與者怨既迎而拒者乖薄施厚望者不報","Ký dụng bất nhiệm giả sơ, hành thưởng lận sắc giả trở, đa hứa thiểu dữ giả oán, ký nghênh nhi cự giả quai, bạc thi hậu vọng giả bất báo,","Đã dùng mà không tin giao thì người xa dần; thưởng mà mặt tiếc rẻ thì người nản; hứa nhiều cho ít thì người oán; đã đón vào rồi lại từ chối thì sinh trái ngang; cho ít mà mong nhiều thì không được đáp lại;"],["絕斥澤惟亟去無留若交軍於斥澤之中必依水草而背衆樹此處斥澤之軍也","Tuyệt xích trạch, duy cức khứ vô lưu, nhược giao quân ư xích trạch chi trung, tất y thuỷ thảo, nhi bối chúng thụ, thử xử xích trạch chi quân dã.","Qua đầm lầy mặn thì phải đi nhanh, đừng dừng lại; nếu buộc phải giao chiến giữa đầm lầy thì phải dựa vào nơi có nước cỏ, lưng tựa vào lùm cây — đó là cách đóng quân ở đầm lầy."],["兵法一曰度二曰量三曰數四曰稱五曰勝地生度度生量量生數數生稱稱生勝","Binh pháp: nhất viết độ, nhị viết lượng, tam viết số, tứ viết xứng, ngũ viết thắng. Địa sinh độ, độ sinh lượng, lượng sinh số, số sinh xứng, xứng sinh thắng.","Phép binh có năm bước: một là đo đất, hai là lượng sức, ba là tính số, bốn là so sánh, năm là thắng. Đất sinh ra việc đo, đo sinh ra lượng, lượng sinh ra số, số sinh ra so sánh, so sánh sinh ra thắng."],["利而誘之亂而取之實而備之強而避之怒而撓之卑而驕之佚而勞之親而離之","Lợi nhi dụ chi, loạn nhi thủ chi, thực nhi bị chi, cường nhi tị chi, nộ nhi nhiễu chi, ti nhi kiêu chi, dật nhi lao chi, thân nhi ly chi.","Địch ham lợi thì dụ bằng lợi, địch rối thì lấy, địch đầy đủ thì phòng bị, địch mạnh thì tránh, địch nóng giận thì chọc cho rối, địch khiêm nhường thì làm cho kiêu, địch nhàn thì làm cho mệt, địch đoàn kết thì chia rẽ."],["同志相得同仁相憂同惡相黨同愛相求同美相妒同智相謀同貴相害同利相忌","Đồng chí tương đắc, đồng nhân tương ưu, đồng ác tương đảng, đồng ái tương cầu, đồng mỹ tương đố, đồng trí tương mưu, đồng quý tương hại, đồng lợi tương kỵ,","Cùng chí hướng thì hợp nhau; cùng lòng nhân thì lo cho nhau; cùng ác thì kết bè; cùng yêu một thứ thì tìm nhau; cùng đẹp thì ghen nhau; cùng khôn thì mưu tính nhau; cùng sang thì hại nhau; cùng lợi thì kỵ nhau;"],["吾所與戰之地不可知不可知則敵所備者多敵所備者多則吾之所與戰者寡矣","Ngô sở dữ chiến chi địa bất khả tri, bất khả tri, tắc địch sở bị giả đa, địch sở bị giả đa, tắc ngô chi sở dữ chiến giả quả hĩ.","Chỗ ta sẽ đánh địch không thể biết; không biết thì địch phải phòng bị nhiều nơi; phòng bị nhiều nơi thì số quân địch phải đối mặt với ta ở từng nơi ít đi."],["富在迎來貧在棄時上無常躁下無疑心輕上生罪侮下無親近臣不重遠臣輕之","Phú tại nghênh lai, bần tại khí thời. Thượng vô thường táo, hạ vô nghi tâm. Khinh thượng sinh tội, vũ hạ vô thân. Cận thần bất trọng, viễn thần khinh chi.","Giàu do biết đón cái đang tới, nghèo do bỏ lỡ thời cơ. Người trên không nóng nảy thất thường thì người dưới không sinh lòng nghi. Khinh người trên thì mắc tội, nhục người dưới thì không còn ai gần. Người gần không được coi trọng thì người xa sẽ coi nhẹ ta."],["故兵有走者有弛者有陷者有崩者有亂者有北者凡此六者非天之災將之過也","Cố binh hữu tẩu giả, hữu trì giả, hữu hãm giả, hữu băng giả, hữu loạn giả, hữu bắc giả. Phàm thử lục giả, phi thiên chi tai, tướng chi quá dã.","Quân có sáu kiểu bại: chạy, lỏng, sa lầy, sụp, rối, thua. Sáu điều này không phải tai hoạ do trời, mà là lỗi của tướng."],["輕聽發言安知非人之譖愬當忍耐三思因事相争焉知非我之不是須平心暗想","Khinh thính phát ngôn, an tri phi nhân chi trấm tố? Đương nhẫn nại tam tư; nhân sự tương tranh, yên tri phi ngã chi bất thị? Tu bình tâm ám tưởng.","Nghe ai nói mà vội tin, biết đâu chẳng phải lời gièm pha vu cáo? Nên nhẫn nại nghĩ kỹ ba lần. Vì việc mà tranh cãi, biết đâu chẳng phải lỗi ở chính mình? Phải bình tâm ngẫm lại."],["國之貧於師者遠輸遠輸則百姓貧近師者貴賣貴賣則百姓財竭財竭則急於丘役","Quốc chi bần ư sư giả viễn thâu, viễn thâu tắc bách tính bần; cận sư giả quý mại, quý mại tắc bách tính tài kiệt, tài kiệt tắc cấp ư khâu dịch.","Nước nghèo vì việc quân là do phải chở lương đi xa; chở xa thì dân nghèo. Nơi gần quân đóng thì giá cả tăng vọt; giá tăng thì dân cạn tiền; cạn tiền thì càng bị thúc thuế thúc phu."],["夫人之所行有道則吉無道則兇吉者百福所歸兇者百禍所攻非其神圣自然所鐘","Phù nhân chi sở hành, hữu đạo tắc cát, vô đạo tắc hung. Cát giả bách phúc sở quy, hung giả bách hoạ sở công, phi kỳ thần thánh, tự nhiên sở chung.","Việc người ta làm, có đạo thì lành, không đạo thì dữ. Lành thì trăm phúc tụ về, dữ thì trăm hoạ kéo đến; không phải do thần thánh gì, mà là lẽ tự nhiên dồn lại."],["夫兵形象水水之行避高而趨下兵之勝避實而擊虛水因地而制行兵因敵而制勝","Phù binh hình tượng thuỷ, thuỷ chi hành, tị cao nhi xu hạ; binh chi thắng, tị thực nhi kích hư. Thuỷ nhân địa nhi chế hành, binh nhân địch nhi chế thắng.","Hình của binh giống như nước: nước chảy thì tránh chỗ cao mà dồn xuống chỗ thấp; binh thắng thì tránh chỗ đặc mà đánh chỗ trống. Nước theo đất mà định dòng chảy; binh theo địch mà định cách thắng."],["孫子曰凡先處戰地而待敵者佚後處戰地而趨戰者勞故善戰者致人而不致於人","Tôn Tử viết: phàm tiên xử chiến địa nhi đãi địch giả dật, hậu xử chiến địa nhi xu chiến giả lao. Cố thiện chiến giả, trí nhân nhi bất trí ư nhân.","Tôn Tử nói: đến chiến địa trước mà chờ địch thì thong thả; đến sau mà vội vã lao vào đánh thì mệt. Vì vậy người giỏi đánh điều khiển người mà không bị người điều khiển."],["故兵非貴益多也惟無武進足以併力料敵取人而已夫惟無慮而易敵者必擒於人","Cố binh phi quý ích đa dã, duy vô vũ tiến, túc dĩ tính lực, liệu địch, thủ nhân nhi dĩ. Phù duy vô lự nhi dị địch giả, tất cầm ư nhân.","Binh không quý ở chỗ càng đông càng tốt; chỉ cần không liều lĩnh xông lên, đủ để dồn sức, lượng địch và thu phục người là được. Kẻ không suy tính mà khinh địch, tất bị người bắt."],["故勝兵若以鎰稱銖敗兵若以銖稱鎰勝者之戰民也若決積水於千仞之溪者形也","Cố thắng binh nhược dĩ dật xứng thù, bại binh nhược dĩ thù xứng dật. Thắng giả chi chiến dân dã, nhược quyết tích thuỷ ư thiên nhẫn chi khê giả, hình dã.","Vì vậy quân thắng như đem một dật mà cân với một thù, quân thua như đem một thù cân với một dật. Người thắng đưa quân vào trận như tháo nước đã dồn sẵn từ khe núi cao nghìn nhẫn đổ xuống — đó là hình."],["聚三軍之衆投之於險此謂將軍之事也九地之變屈伸之利人情之理不可不察也","Tụ tam quân chi chúng, đầu chi ư hiểm, thử vị tướng quân chi sự dã. Cửu địa chi biến, khuất thân chi lợi, nhân tình chi lý, bất khả bất sát dã.","Gom cả ba quân mà đặt vào chỗ hiểm — đó là việc của tướng. Sự biến hoá của chín loại đất, cái lợi của co và duỗi, lẽ thường của lòng người, không thể không xét kỹ."],["軍政曰言不相聞故為金鼓視不相見故為旌旗夫金鼓旌旗者所以一民之耳目也","Quân chính viết: ngôn bất tương văn, cố vi kim cổ; thị bất tương kiến, cố vi tinh kỳ. Phù kim cổ tinh kỳ giả, sở dĩ nhất dân chi nhĩ mục dã.","Sách Quân chính nói: nói không nghe được nhau nên đặt ra chiêng trống; nhìn không thấy được nhau nên đặt ra cờ xí. Chiêng trống cờ xí là để làm cho tai mắt của mọi người thành một."],["平陸處易而右背高前死後生此處平陸之軍也凡此四軍之利黃帝之所以勝四帝也","Bình lục xử dị, nhi hữu bối cao, tiền tử hậu sinh, thử xử bình lục chi quân dã. Phàm thử tứ quân chi lợi, Hoàng Đế chi sở dĩ thắng tứ đế dã.","Ở đồng bằng thì chọn chỗ dễ đi lại, phía phải và sau lưng tựa vào chỗ cao, phía trước là đất thấp hiểm, phía sau là đất cao sống — đó là cách đóng quân ở đồng bằng. Bốn cách đóng quân ấy là điều Hoàng Đế nhờ đó thắng bốn vua khác."],["木石之性安則靜危則動方則止圓則行故善戰人之勢如轉圓石於千仞之山者勢也","Mộc thạch chi tính, an tắc tĩnh, nguy tắc động, phương tắc chỉ, viên tắc hành. Cố thiện chiến nhân chi thế, như chuyển viên thạch ư thiên nhẫn chi sơn giả, thế dã.","Tính của gỗ đá là ở chỗ bằng thì nằm yên, ở chỗ dốc thì lăn, vuông thì dừng, tròn thì chạy. Vì vậy thế của người giỏi dùng quân như lăn đá tròn từ núi cao nghìn nhẫn — đó là thế."],["棄玉取石者盲羊質虎皮者飾衣不舉領者倒走不視地者顛柱弱者屋壞輔弱者國傾","Khí ngọc thủ thạch giả manh, dương chất hổ bì giả sức. Y bất cử lĩnh giả đảo, tẩu bất thị địa giả điên. Trụ nhược giả ốc hoại, phụ nhược giả quốc khuynh.","Bỏ ngọc lấy đá là mù; chất dê mà khoác da hổ là tô vẽ bên ngoài. Mặc áo mà không cầm lấy cổ áo thì lộn ngược; chạy mà không nhìn đất thì vấp ngã. Cột yếu thì nhà đổ; người phụ tá yếu thì nước nghiêng."],["聽讒而美聞諫而仇者亡能有其有者安貪人之有者殘右第五章言遵而行之者義也","Thính sàm nhi mỹ, văn gián nhi cừu giả vong. Năng hữu kỳ hữu giả an, tham nhân chi hữu giả tàn. Hữu đệ ngũ chương, ngôn tuân nhi hành chi giả nghĩa dã.","Nghe lời gièm thì thấy hay, nghe lời can thì coi là thù — kẻ ấy sẽ mất. Biết giữ cái mình có thì yên; tham cái của người thì tàn. Trên đây là chương năm, nói rằng theo đó mà làm là nghĩa."],["孫子曰凡用兵之法有散地有輕地有爭地有交地有衢地有重地有圮地有圍地有死地","Tôn Tử viết: phàm dụng binh chi pháp, hữu tán địa, hữu khinh địa, hữu tranh địa, hữu giao địa, hữu cù địa, hữu trọng địa, hữu bĩ địa, hữu vi địa, hữu tử địa.","Tôn Tử nói: theo phép dùng binh, có đất tan, đất nhẹ, đất tranh, đất giao, đất ngã tư, đất nặng, đất lở, đất vây, đất chết."],["我出而不利彼出而不利曰支支形者敵雖利我我無出也引而去之令敵半出而擊之利","Ngã xuất nhi bất lợi, bỉ xuất nhi bất lợi, viết chi. Chi hình giả, địch tuy lợi ngã, ngã vô xuất dã, dẫn nhi khứ chi, lệnh địch bán xuất nhi kích chi, lợi.","Ta ra trước thì bất lợi, địch ra trước cũng bất lợi, gọi là đất chia. Ở đất chia, dù địch bày lợi để nhử, ta cũng không ra; ta rút lui dụ địch ra được nửa đường rồi đánh thì lợi."],["故策之而知得失之計作之而知動靜之理形之而知死生之地角之而知有餘不足之處","Cố sách chi nhi tri đắc thất chi kế, tác chi nhi tri động tĩnh chi lý, hình chi nhi tri tử sinh chi địa, giác chi nhi tri hữu dư bất túc chi xứ.","Vì vậy phải tính toán để biết kế hoạch của địch được mất chỗ nào, khích động để biết lẽ động tĩnh của họ, bày hình để biết chỗ nào là đất chết đất sống, thăm dò để biết chỗ nào họ dư chỗ nào họ thiếu."],["貴而忘賤者不久念舊怨而棄新功者兇用人不得正者殆強用人者不畜為人擇官者亂","Quý nhi vong tiện giả bất cửu, niệm cựu oán nhi khí tân công giả hung, dụng nhân bất đắc chính giả đãi, cưỡng dụng nhân giả bất súc, vị nhân trạch quan giả loạn,","Giàu sang mà quên lúc nghèo hèn thì không bền; nhớ oán cũ mà bỏ công mới thì xấu; dùng người không ngay thẳng thì nguy; ép người làm việc họ không muốn thì không giữ được họ; vì một người mà đặt ra chức vụ thì loạn;"],["地薄者大物不產水淺者大物不游樹禿者大禽不棲林疏者大獸不居山峭者崩澤滿者溢","Địa bạc giả đại vật bất sản, thuỷ thiển giả đại vật bất du, thụ ngốc giả đại cầm bất thê, lâm sơ giả đại thú bất cư. Sơn tiễu giả băng, trạch mãn giả dật.","Đất cằn không sinh vật lớn, nước nông không có cá lớn bơi, cây trụi không có chim lớn đậu, rừng thưa không có thú lớn ở. Núi quá dốc thì sụp, đầm quá đầy thì tràn."],["怨在不舍小過患在不預定謀福在積善禍在積惡饑在賤農寒在惰織安在得人危在失事","Oán tại bất xả tiểu quá, hoạn tại bất dự định mưu. Phúc tại tích thiện, hoạ tại tích ác, cơ tại tiện nông, hàn tại nọa chức, an tại đắc nhân, nguy tại thất sự.","Oán sinh từ chỗ không bỏ qua lỗi nhỏ; hoạn nạn sinh từ chỗ không tính trước. Phúc do tích điều thiện, hoạ do tích điều ác, đói do coi rẻ nghề nông, lạnh do lười dệt, yên do được người, nguy do để hỏng việc."],["戰士貧游士富者衰貨賂公行者昧聞善忽略記過不忘者暴所任不可信所信不可任者濁","Chiến sĩ bần, du sĩ phú giả suy, hoá lộ công hành giả muội, văn thiện hốt lược, ký quá bất vong giả bạo, sở nhiệm bất khả tín, sở tín bất khả nhiệm giả trọc,","Người lính chiến nghèo mà kẻ nói suông giàu thì suy; của hối lộ công khai qua lại thì tối tăm; nghe điều tốt thì bỏ qua, nhớ lỗi thì không quên là tàn bạo; người được giao việc thì không đáng tin, người đáng tin thì không được giao việc là đục;"],["敢問兵可使如率然乎曰可夫吳人與越人相惡也當其同舟而濟遇風其相救也如左右手","Cảm vấn: binh khả sử như suất nhiên hồ? Viết: khả. Phù Ngô nhân dữ Việt nhân tương ố dã, đương kỳ đồng chu nhi tế. Ngộ phong, kỳ tương cứu dã, như tả hữu thủ.","Xin hỏi: có thể làm cho quân như Suất nhiên không? Đáp: được. Người Ngô và người Việt vốn ghét nhau, nhưng khi cùng ngồi một thuyền qua sông, gặp gió lớn, họ cứu nhau như tay trái tay phải."],["與覆車同軌者傾與亡國同事者滅見已生者慎將生惡其跡者須避之畏危者安畏亡者存","Dữ phúc xa đồng quỹ giả khuynh, dữ vong quốc đồng sự giả diệt. Kiến dĩ sinh giả thận tương sinh, ố kỳ tích giả tu tị chi. Uý nguy giả an, uý vong giả tồn.","Đi cùng vết xe đã đổ thì cũng đổ; làm cùng việc của nước đã mất thì cũng mất. Thấy việc đã xảy ra thì phải thận trọng với việc sắp xảy ra; ghét dấu vết của nó thì phải tránh con đường ấy. Biết sợ nguy thì yên, biết sợ mất thì còn."],["夫志心篤行之術長莫長于博謀安莫安于忍辱先莫先于修德樂莫樂于好善神莫神于至誠","Phù chí tâm đốc hạnh chi thuật, trường mạc trường vu bác mưu, an mạc an vu nhẫn nhục, tiên mạc tiên vu tu đức, lạc mạc lạc vu hiếu thiện, thần mạc thần vu chí thành;","Phép giữ chí bền lòng, làm việc chắc chắn: không gì lâu dài bằng mưu tính rộng, không gì yên ổn bằng chịu được nhục, không gì đi trước bằng sửa đức, không gì vui bằng ham điều thiện, không gì thần diệu bằng hết lòng thành;"],["故善用兵者譬如率然率然者常山之蛇也擊其首則尾至擊其尾則首至擊其中則首尾俱至","Cố thiện dụng binh giả, thí như suất nhiên. Suất nhiên giả, Thường sơn chi xà dã. Kích kỳ thủ tắc vĩ chí, kích kỳ vĩ tắc thủ chí, kích kỳ trung tắc thủ vĩ câu chí.","Người giỏi dùng binh giống như con rắn Suất nhiên. Suất nhiên là rắn ở núi Thường Sơn: đánh đầu thì đuôi tới cứu, đánh đuôi thì đầu tới cứu, đánh giữa thì đầu đuôi cùng tới."],["故用間有五有鄉間有內間有反間有死間有生間五間俱起莫知其道是謂神紀人君之寶也","Cố dụng gián hữu ngũ: hữu hương gián, hữu nội gián, hữu phản gián, hữu tử gián, hữu sinh gián. Ngũ gián câu khởi, mạc tri kỳ đạo, thị vị thần kỷ, nhân quân chi bảo dã.","Dùng gián điệp có năm loại: gián điệp địa phương, gián điệp trong nội bộ địch, gián điệp phản lại, gián điệp chết, gián điệp sống. Năm loại cùng hoạt động mà không ai biết đường lối, gọi là “thần kỷ” — kỷ cương thần diệu, là báu vật của người làm vua."],["是故散地吾將一其志輕地吾將使之屬爭地吾將趨其後交地吾將謹其守衢地吾將固其結","Thị cố tán địa, ngô tương nhất kỳ chí; khinh địa, ngô tương sử chi thuộc; tranh địa, ngô tương xu kỳ hậu; giao địa, ngô tương cẩn kỳ thủ; cù địa, ngô tương cố kỳ kết;","Vì vậy ở đất tan, ta sẽ làm cho quân chung một chí; đất nhẹ, ta sẽ làm cho các bộ phận nối liền nhau; đất tranh, ta sẽ đánh vào phía sau địch; đất giao, ta sẽ giữ cẩn thận; đất ngã tư, ta sẽ củng cố mối giao kết;"],["賢人君子明于盛衰之道通乎成敗之數審乎治亂之勢達乎去就之理故潛居抱道以待其時","Hiền nhân quân tử minh vu thịnh suy chi đạo, thông hồ thành bại chi số, thẩm hồ trị loạn chi thế, đạt hồ khứ tựu chi lý, cố tiềm cư bão đạo, dĩ đãi kỳ thời.","Người hiền, người quân tử hiểu rõ lẽ thịnh suy, thông cái số thành bại, xét kỹ thế trị loạn, thấu lý nên đi hay nên ở; vì vậy họ ẩn mình giữ đạo mà chờ thời."],["先暴而後畏其衆者不精之至也來委謝者欲休息也兵怒而相迎久而不合又不相去必謹察之","Tiên bạo nhi hậu uý kỳ chúng giả, bất tinh chi chí dã; lai uỷ tạ giả, dục hưu tức dã. Binh nộ nhi tương nghênh, cửu nhi bất hợp, hựu bất tương khứ, tất cẩn sát chi.","Trước thì tàn bạo với quân, sau lại sợ quân — là kẻ cầm quân kém cỏi đến cùng cực; sai người đến xin lỗi tặng quà là muốn nghỉ ngơi. Quân địch hùng hổ kéo đến đối mặt mà lâu không giao chiến, cũng không rút đi, thì phải xét thật kỹ."],["凡為客之道深入則專主人不克掠于饒野三軍足食謹養而勿勞併氣積力運兵計謀為不可測","Phàm vi khách chi đạo, thâm nhập tắc chuyên, chủ nhân bất khắc. Lược vu nhiêu dã, tam quân túc thực. Cẩn dưỡng nhi vật lao, tính khí tích lực, vận binh kế mưu, vi bất khả trắc.","Phép làm khách trên đất người: vào sâu thì quân chuyên nhất, chủ nhà không thắng được. Lấy lương ở vùng đồng ruộng trù phú thì ba quân đủ ăn. Chăm nuôi quân, đừng làm họ mệt, dồn khí tích sức, điều quân bày mưu, khiến địch không lường được."],["守職而不廢處義而不回見嫌而不茍免見利而不茍得此人之杰也右第二章言道不可以非正","Thủ chức nhi bất phế, xử nghĩa nhi bất hồi, kiến hiềm nhi bất cẩu miễn, kiến lợi nhi bất cẩu đắc, thử nhân chi kiệt dã. Hữu đệ nhị chương, ngôn đạo bất khả dĩ phi chính.","Giữ chức phận mà không bỏ bê, đứng về phía nghĩa mà không quay lưng, gặp việc dễ bị nghi mà không tìm cách trốn cho rẻ, gặp lợi mà không cẩu thả nhận lấy — đó là bậc kiệt xuất. Trên đây là chương hai, nói rằng đạo không thể không chính."],["將不通於九變之利雖知地形不能得地之利矣治兵不知九變之術雖知地利不能得人之用矣","Tướng bất thông ư cửu biến chi lợi, tuy tri địa hình, bất năng đắc địa chi lợi hĩ; trị binh bất tri cửu biến chi thuật, tuy tri địa lợi, bất năng đắc nhân chi dụng hĩ.","Tướng không thông cái lợi của chín điều biến hoá thì dù biết địa hình cũng không lấy được lợi của đất; cai quản quân mà không biết thuật biến hoá thì dù biết lợi của đất cũng không dùng được sức người."],["投之無所往死且不北死焉不得士人盡力兵士甚陷則不懼無所往則固深入則拘不得已則鬥","Đầu chi vô sở vãng, tử thả bất bắc. Tử yên bất đắc, sĩ nhân tận lực. Binh sĩ thậm hãm tắc bất cụ, vô sở vãng tắc cố, thâm nhập tắc câu, bất đắc dĩ tắc đấu.","Đặt quân vào chỗ không còn đường đi, thì chết cũng không chạy. Đã không thể tránh cái chết, binh sĩ sẽ dốc hết sức. Lính lâm vào thế quá hiểm thì không còn sợ, không có đường đi thì vững, vào sâu thì gắn chặt nhau, bất đắc dĩ thì chiến đấu."],["故君之所以患於軍者三不知軍之不可以進而謂之進不知軍之不可以退而謂之退是為縻軍","Cố quân chi sở dĩ hoạn ư quân giả tam: bất tri quân chi bất khả dĩ tiến nhi vị chi tiến, bất tri quân chi bất khả dĩ thoái nhi vị chi thoái, thị vi mi quân;","Vua gây hại cho quân có ba điều: không biết quân không thể tiến mà bắt tiến, không biết quân không thể lui mà bắt lui — thế gọi là trói quân;"],["三軍可奪氣將軍可奪心是故朝氣銳晝氣惰暮氣歸故善用兵者避其銳氣擊其惰歸此治氣者也","Tam quân khả đoạt khí, tướng quân khả đoạt tâm. Thị cố triêu khí nhuệ, trú khí nọa, mộ khí quy. Cố thiện dụng binh giả, tị kỳ nhuệ khí, kích kỳ nọa quy, thử trị khí giả dã;","Có thể làm nhụt khí cả ba quân, có thể làm nao lòng vị tướng. Khí buổi sáng thì hăng, buổi trưa thì lười, buổi chiều thì muốn về. Vì vậy người giỏi dùng binh tránh lúc địch hăng, đánh lúc địch lười và muốn về — đó là cách trị khí;"],["夫地形者兵之助也料敵制勝計險厄遠近上將之道也知此而用戰者必勝不知此而用戰者必敗","Phù địa hình giả, binh chi trợ dã. Liệu địch chế thắng, kế hiểm ách viễn cận, thượng tướng chi đạo dã. Tri thử nhi dụng chiến giả tất thắng, bất tri thử nhi dụng chiến giả tất bại.","Địa hình là cái giúp cho việc binh. Lượng địch mà định cách thắng, tính chỗ hiểm chỗ hẹp, xa gần — đó là đạo của bậc tướng giỏi. Biết điều này mà đánh thì tất thắng; không biết mà đánh thì tất thua."],["孫子曰凡用兵之法將受命於君合軍聚衆交和而舍莫難於軍爭軍爭之難者以迂為直以患為利","Tôn Tử viết: phàm dụng binh chi pháp, tướng thụ mệnh ư quân, hợp quân tụ chúng, giao hoà nhi xá, mạc nan ư quân tranh. Quân tranh chi nan giả, dĩ vu vi trực, dĩ hoạn vi lợi.","Tôn Tử nói: phép dùng binh, tướng nhận lệnh vua, họp quân tụ người, đóng trại đối diện địch — không gì khó bằng tranh giành lợi thế. Cái khó của tranh lợi thế là biến đường vòng thành đường thẳng, biến điều bất lợi thành có lợi."],["故兵無成勢無恒形能因敵變化而取勝者謂之神故五行無常勝四時無常位日有短長月有死生","Cố binh vô thành thế, vô hằng hình, năng nhân địch biến hoá nhi thủ thắng giả, vị chi thần. Cố ngũ hành vô thường thắng, tứ thời vô thường vị, nhật hữu đoản trường, nguyệt hữu tử sinh.","Vì vậy binh không có thế sẵn, không có hình cố định; biết theo địch mà biến hoá để giành thắng thì gọi là thần. Năm hành không hành nào thắng mãi, bốn mùa không mùa nào ở yên, ngày có ngắn dài, trăng có tròn khuyết."],["敵近而靜者恃其險也遠而挑戰者欲人之進也其所居易者利也衆樹動者來也衆草多障者疑也","Địch cận nhi tĩnh giả, thị kỳ hiểm dã; viễn nhi khiêu chiến giả, dục nhân chi tiến dã; kỳ sở cư dị giả, lợi dã; chúng thụ động giả, lai dã; chúng thảo đa chướng giả, nghi dã;","Địch ở gần mà yên lặng là vì họ cậy có địa thế hiểm; ở xa mà khiêu chiến là muốn ta tiến tới; đóng ở nơi bằng phẳng dễ đi là vì có lợi cho họ; cây rừng lay động là họ đang đến; cỏ bị buộc thành nhiều chướng ngại là họ muốn ta nghi ngờ;"],["粟馬肉食軍無懸缻而不返其舍者窮寇也諄諄翕翕徐與人言者失衆也數賞者窘也數罰者困也","Túc mã nhục thực, quân vô huyền phẫu, nhi bất phản kỳ xá giả, cùng khấu dã; truân truân hấp hấp, từ dữ nhân ngôn giả, thất chúng dã; sác thưởng giả, quẫn dã; sác phạt giả, khốn dã;","Lấy thóc cho ngựa ăn, giết súc vật kéo xe lấy thịt cho lính ăn, trong quân không còn treo nồi, không về trại nghỉ nữa — là giặc đã cùng đường, quyết liều; tướng nói với quân rề rà, nhỏ nhẹ, lặp đi lặp lại — là đã mất lòng quân; thưởng liên tục là đang bí; phạt liên tục là đang khốn;"],["聲不過五五聲之變不可勝聽也色不過五五色之變不可勝觀也味不過五五味之變不可勝嘗也","Thanh bất quá ngũ, ngũ thanh chi biến, bất khả thắng thính dã; sắc bất quá ngũ, ngũ sắc chi biến, bất khả thắng quan dã; vị bất quá ngũ, ngũ vị chi biến, bất khả thắng thường dã;","Âm chỉ có năm, nhưng năm âm biến hoá thì nghe không hết; màu chỉ có năm, nhưng năm màu biến hoá thì nhìn không hết; vị chỉ có năm, nhưng năm vị biến hoá thì nếm không hết;"],["凡戰者以正合以奇勝故善出奇者無窮如天地不竭如江海終而復始日月是也死而復生四時是也","Phàm chiến giả, dĩ chính hợp, dĩ kỳ thắng. Cố thiện xuất kỳ giả, vô cùng như thiên địa, bất kiệt như giang hải. Chung nhi phục thủy, nhật nguyệt thị dã. Tử nhi phục sinh, tứ thời thị dã.","Đánh trận thì dùng chính binh để giao chiến, dùng kỳ binh để thắng. Người giỏi ra kỳ binh thì vô cùng như trời đất, không cạn như sông biển; hết rồi lại bắt đầu như mặt trời mặt trăng, chết rồi lại sống như bốn mùa."],["凡軍之所欲擊城之所欲攻人之所欲殺必先知其守將左右謁者門者舍人之姓名令吾間必索知之","Phàm quân chi sở dục kích, thành chi sở dục công, nhân chi sở dục sát, tất tiên tri kỳ thủ tướng, tả hữu, yết giả, môn giả, xá nhân chi tính danh, lệnh ngô gián tất sách tri chi.","Quân muốn đánh nơi nào, thành muốn công nơi nào, người muốn diệt là ai, đều phải biết trước tên họ của tướng giữ nơi ấy, người thân cận, người tiếp khách, người canh cửa, người hầu, sai gián điệp của ta phải dò ra cho hết."],["夫勢均以一擊十曰走卒强吏弱曰弛吏强卒弱曰陷大吏怒而不服遇敵懟而自戰將不知其能曰崩","Phù thế quân, dĩ nhất kích thập, viết tẩu; tốt cường lại nhược, viết trì; lại cường tốt nhược, viết hãm; đại lại nộ nhi bất phục, ngộ địch đỗi nhi tự chiến, tướng bất tri kỳ năng, viết băng;","Thế ngang nhau mà lấy một đánh mười, gọi là chạy; lính mạnh mà quan yếu, gọi là lỏng; quan mạnh mà lính yếu, gọi là sa lầy; tướng dưới giận mà không phục, gặp địch tự ý đánh vì oán, tướng trên không biết năng lực của họ, gọi là sụp;"],["故兵以詐立以利動以分合為變者也故其疾如風其徐如林侵掠如火不動如山難知如陰動如雷震","Cố binh dĩ trá lập, dĩ lợi động, dĩ phân hợp vi biến giả dã. Cố kỳ tật như phong, kỳ từ như lâm, xâm lược như hoả, bất động như sơn, nan tri như âm, động như lôi chấn.","Binh dựa vào biến hoá khó lường mà đứng, dựa vào lợi mà động, dựa vào chia và hợp mà thay đổi. Vì vậy nhanh như gió, chậm rãi như rừng, tràn tới như lửa, đứng yên như núi, kín như bóng tối, động như sấm sét."],["激水之疾至於漂石者勢也鷙鳥之疾至於毀折者節也故善戰者其勢險其節短勢如彍弩節如發機","Kích thuỷ chi tật, chí ư phiêu thạch giả, thế dã; chí điểu chi tật, chí ư huỷ chiết giả, tiết dã. Cố thiện chiến giả, kỳ thế hiểm, kỳ tiết đoản. Thế như khoách nỗ, tiết như phát cơ.","Nước chảy xiết đến mức cuốn được đá, là nhờ thế; chim săn lao nhanh đến mức bẻ gãy con mồi, là nhờ nhịp. Vì vậy người giỏi đánh có thế hiểm mà nhịp ngắn. Thế như nỏ đã giương hết, nhịp như lúc bật lẫy."],["孫子曰凡興師十萬出征千里百姓之費公家之奉日費千金內外騷動怠于道路不得操事者七十萬家","Tôn Tử viết: phàm hưng sư thập vạn, xuất chinh thiên lý, bách tính chi phí, công gia chi phụng, nhật phí thiên kim, nội ngoại tao động, đãi vu đạo lộ, bất đắc thao sự giả, thất thập vạn gia.","Tôn Tử nói: dấy quân mười vạn, đi đánh xa nghìn dặm, tiền của dân, chi phí của nhà nước mỗi ngày tốn nghìn vàng, trong ngoài náo động, dân mệt mỏi trên đường vận chuyển, không làm ăn được — tới bảy mươi vạn nhà."],["怒可以復喜慍可以復悅亡國不可以復存死者不可以復生故明主慎之良將警之此安國全軍之道也","Nộ khả dĩ phục hỉ, uấn khả dĩ phục duyệt, vong quốc bất khả dĩ phục tồn, tử giả bất khả dĩ phục sinh. Cố minh chủ thận chi, lương tướng cảnh chi, thử an quốc toàn quân chi đạo dã.","Giận rồi có thể vui lại, bực rồi có thể hoà lại, nhưng nước mất không thể còn lại, người chết không thể sống lại. Vì vậy vua sáng phải thận trọng, tướng tốt phải cảnh giác — đó là đường giữ yên nước, giữ trọn quân."],["故兵聞拙速未睹巧之久也夫兵久而國利者未之有也故不盡知用兵之害者則不能盡知用兵之利也","Cố binh văn chuyết tốc, vị đổ xảo chi cửu dã. Phù binh cửu nhi quốc lợi giả, vị chi hữu dã. Cố bất tận tri dụng binh chi hại giả, tắc bất năng tận tri dụng binh chi lợi dã.","Vì vậy việc binh nghe nói có cái vụng mà nhanh, chưa thấy cái khéo mà lâu bao giờ. Đánh lâu mà nước được lợi, chưa từng có. Cho nên ai không biết hết cái hại của việc binh thì cũng không thể biết hết cái lợi của nó."],["是故方馬埋輪未足恃也齊勇如一政之道也剛柔皆得地之理也故善用兵者攜手若使一人不得已也","Thị cố phương mã mai luân, vị túc thị dã; tề dũng như nhất, chính chi đạo dã; cương nhu giai đắc, địa chi lý dã. Cố thiện dụng binh giả, huề thủ nhược sử nhất nhân, bất đắc dĩ dã.","Vì vậy buộc ngựa lại chôn bánh xe để quân không chạy, chưa đủ để tin cậy; làm cho mọi người đều dũng cảm như một mới là đạo trị quân; cứng và mềm đều dùng được là nhờ hiểu lẽ của đất. Người giỏi dùng binh dắt tay cả quân như dắt một người, vì đã đặt họ vào thế không thể khác."],["鳥起者伏也獸駭者覆也塵高而銳者車來也卑而廣者徒來也散而條達者樵采也少而往來者營軍也","Điểu khởi giả, phục dã; thú hãi giả, phúc dã; trần cao nhi nhuệ giả, xa lai dã; ti nhi quảng giả, đồ lai dã; tán nhi điều đạt giả, tiều thái dã; thiểu nhi vãng lai giả, doanh quân dã;","Chim bay vụt lên là có quân phục; thú hoang chạy hoảng là có quân tập kích; bụi bốc cao mà nhọn là xe đang đến; bụi thấp mà lan rộng là bộ binh đang đến; bụi tản ra từng vệt là họ đang kiếm củi; bụi ít mà lúc có lúc không là họ đang dựng trại;"],["力屈財殫中原內虛於家百姓之費十去其七公家之費破車罷馬甲胄矢弩戟楯蔽櫓丘牛大車十去其六","Lực khuất tài đàn, trung nguyên nội hư ư gia. Bách tính chi phí, thập khứ kỳ thất; công gia chi phí, phá xa bì mã, giáp trụ thỉ nỗ, kích thuẫn tế lỗ, khâu ngưu đại xa, thập khứ kỳ lục.","Sức kiệt của hết, trong nước nhà nhà trống rỗng. Của dân mười phần mất bảy; của nhà nước thì xe hỏng ngựa mệt, giáp mũ cung tên, giáo mộc thuẫn lớn, trâu kéo xe nặng, mười phần mất sáu."],["卒未親附而罰之則不服不服則難用也卒已親附而罰不行則不可用也故令之以文齊之以武是謂必取","Tốt vị thân phụ nhi phạt chi, tắc bất phục, bất phục tắc nan dụng dã. Tốt dĩ thân phụ nhi phạt bất hành, tắc bất khả dụng dã. Cố lệnh chi dĩ văn, tề chi dĩ vũ, thị vị tất thủ.","Quân chưa gắn bó với mình mà đã phạt thì họ không phục, không phục thì khó dùng. Quân đã gắn bó mà phạt không thi hành thì cũng không dùng được. Vì vậy dạy bảo bằng ân tình, chỉnh đốn bằng kỷ luật — thế gọi là chắc thắng."],["因形而措勝於衆衆不能知人皆知我所以勝之形而莫知吾所以制勝之形故其戰勝不復而應形於無窮","Nhân hình nhi thố thắng ư chúng, chúng bất năng tri. Nhân giai tri ngã sở dĩ thắng chi hình, nhi mạc tri ngô sở dĩ chế thắng chi hình. Cố kỳ chiến thắng bất phục, nhi ứng hình ư vô cùng.","Dựa vào hình của địch mà sắp đặt cách thắng trước mắt mọi người, mà mọi người không hiểu nổi. Ai cũng thấy được hình mà ta dùng để thắng, nhưng không ai biết cách ta tạo ra cái thắng ấy. Vì vậy mỗi lần thắng không lặp lại, mà ứng theo hình của địch đến vô cùng."],["因是而知之故鄉間內間可得而使也因是而知之故死間為誑事可使告敵因是而知之故生間可使如期","Nhân thị nhi tri chi, cố hương gián, nội gián khả đắc nhi sử dã; nhân thị nhi tri chi, cố tử gián vi cuống sự, khả sử cáo địch; nhân thị nhi tri chi, cố sinh gián khả sử như kỳ.","Nhờ gián điệp phản lại mà biết được tình hình, nên mới dùng được gián điệp địa phương và gián điệp nội bộ; nhờ đó mà biết, nên gián điệp chết mới bày được việc giả để báo cho địch; nhờ đó mà biết, nên gián điệp sống mới về báo đúng hẹn."],["將軍之事靜以幽正以治能愚士卒之耳目使之無知易其事革其謀使人無識易其居迂其途使人不得慮","Tướng quân chi sự, tĩnh dĩ u, chính dĩ trị. Năng ngu sĩ tốt chi nhĩ mục, sử chi vô tri; dịch kỳ sự, cách kỳ mưu, sử nhân vô thức; dịch kỳ cư, vu kỳ đồ, sử nhân bất đắc lự.","Việc của tướng là lặng lẽ mà sâu kín, ngay thẳng mà có trật tự. Có thể che tai mắt của binh sĩ, khiến họ không biết kế hoạch; thay đổi việc làm, đổi mưu kế, khiến người không nhận ra; đổi nơi đóng, đi đường vòng, khiến người không đoán được."],["帥與之期如登高而去其梯帥與之深入諸侯之地而發其機焚舟破釜若驅群羊驅而往驅而來莫知所之","Suý dữ chi kỳ, như đăng cao nhi khứ kỳ thê; suý dữ chi thâm nhập chư hầu chi địa, nhi phát kỳ cơ, phần chu phá phủ, nhược khu quần dương. Khu nhi vãng, khu nhi lai, mạc tri sở chi.","Tướng hẹn quân vào trận như đưa người lên cao rồi rút thang; tướng đưa quân vào sâu đất người rồi mới bật lẫy, đốt thuyền đập nồi, như xua một đàn dê. Xua đi, xua lại, không ai biết sẽ đến đâu."],["故三軍之事莫親於間賞莫厚於間事莫密於間非聖智不能用間非仁義不能使間非微妙不能得間之實","Cố tam quân chi sự, mạc thân ư gián, thưởng mạc hậu ư gián, sự mạc mật ư gián, phi thánh trí bất năng dụng gián, phi nhân nghĩa bất năng sử gián, phi vi diệu bất năng đắc gián chi thực.","Trong việc ba quân, không ai được gần gũi bằng gián điệp, không ai được thưởng hậu bằng gián điệp, không việc gì kín bằng việc gián điệp. Không phải bậc thánh trí thì không dùng được gián điệp; không có nhân nghĩa thì không sai được gián điệp; không tinh tế thì không lấy được tin thật từ gián điệp."],["民既專一則勇者不得獨進怯者不得獨退此用衆之法也故夜戰多金鼓晝戰多旌旗所以變人之耳目也","Dân ký chuyên nhất, tắc dũng giả bất đắc độc tiến, khiếp giả bất đắc độc thoái, thử dụng chúng chi pháp dã. Cố dạ chiến đa kim cổ, trú chiến đa tinh kỳ, sở dĩ biến nhân chi nhĩ mục dã.","Mọi người đã thành một, thì kẻ gan không được tiến một mình, kẻ nhát không được lùi một mình — đó là phép dùng số đông. Vì vậy đánh đêm dùng nhiều chiêng trống, đánh ngày dùng nhiều cờ xí, để thích ứng với tai mắt người."],["相守數年以爭一日之勝而愛爵祿百金不知敵之情者不仁之至也非人之將也非主之佐也非勝之主也","Tương thủ sổ niên, dĩ tranh nhất nhật chi thắng, nhi ái tước lộc bách kim, bất tri địch chi tình giả, bất nhân chi chí dã, phi nhân chi tướng dã, phi chủ chi tá dã, phi thắng chi chủ dã.","Giằng co nhau mấy năm để tranh cái thắng trong một ngày, mà lại tiếc chút bổng lộc trăm vàng, không chịu tìm hiểu tình hình địch — đó là bất nhân đến cùng cực, không phải tướng của người, không phải người giúp vua, không phải chủ của chiến thắng."],["短莫短于茍得幽莫幽于貪鄙孤莫孤于自恃危莫危于任疑敗莫敗于多私右第四章言本宗不可以離德","Đoản mạc đoản vu cẩu đắc, u mạc u vu tham bỉ, cô mạc cô vu tự thị, nguy mạc nguy vu nhiệm nghi, bại mạc bại vu đa tư. Hữu đệ tứ chương, ngôn bản tông bất khả dĩ ly đức.","Không gì ngắn ngủi bằng cái được một cách cẩu thả, không gì tối tăm bằng tham lam hèn mọn, không gì cô độc bằng chỉ cậy vào mình, không gì nguy bằng giao việc cho người mình còn ngờ, không gì thất bại bằng lắm việc riêng tư. Trên đây là chương bốn, nói rằng gốc và chủ không thể rời khỏi đức."],["同聲相應同氣相感同類相依同義相親同難相濟同道相成同藝相規同巧相勝此乃數之所得不有與理違","Đồng thanh tương ứng, đồng khí tương cảm, đồng loại tương y, đồng nghĩa tương thân, đồng nạn tương tế, đồng đạo tương thành, đồng nghệ tương quy, đồng xảo tương thắng, thử nãi số chi sở đắc, bất hữu dữ lý vi.","Cùng tiếng thì hưởng ứng nhau; cùng khí thì cảm nhau; cùng loại thì dựa nhau; cùng nghĩa thì thân nhau; cùng gặp nạn thì cứu nhau; cùng đạo thì giúp nhau thành; cùng nghề thì soi xét nhau; cùng khéo thì ganh thắng nhau. Đó là lẽ số tự nhiên, không có gì trái với lý."],["故用兵之法十則圍之五則攻之倍則分之敵則能戰之少則能守之不若則能避之故小敵之堅大敵之擒也","Cố dụng binh chi pháp, thập tắc vi chi, ngũ tắc công chi, bội tắc phân chi, địch tắc năng chiến chi, thiểu tắc năng thủ chi, bất nhược tắc năng tị chi. Cố tiểu địch chi kiên, đại địch chi cầm dã.","Phép dùng binh: gấp mười thì vây, gấp năm thì đánh, gấp đôi thì chia địch ra, ngang nhau thì có thể đánh, ít hơn thì phải biết giữ, kém hẳn thì phải biết tránh. Quân nhỏ mà cứ cố cứng đầu thì chỉ thành tù binh của quân lớn."],["故用兵之法高陵勿向背丘勿逆佯北勿從銳卒勿攻餌兵勿食歸師勿遏圍師必闕窮寇勿迫此用兵之法也","Cố dụng binh chi pháp, cao lăng vật hướng, bối khâu vật nghịch, dương bắc vật tòng, nhuệ tốt vật công, nhị binh vật thực, quy sư vật át, vi sư tất khuyết, cùng khấu vật bách, thử dụng binh chi pháp dã.","Phép dùng binh: địch ở gò cao thì đừng đánh lên, địch dựa lưng vào đồi thì đừng đánh ngược, địch giả thua chạy thì đừng đuổi, quân tinh nhuệ của địch thì đừng đánh, quân làm mồi thì đừng cắn, quân đang rút về thì đừng chặn, vây địch thì phải để hở một lối, giặc đã cùng đường thì đừng dồn ép — đó là phép dùng binh."],["敢問敵衆整而將來待之若何曰先奪其所愛則聽矣故兵之情主速乘人之不及由不虞之道攻其所不戒也","Cảm vấn: địch chúng chỉnh nhi tương lai, đãi chi nhược hà? Viết: tiên đoạt kỳ sở ái, tắc thính hĩ. Cố binh chi tình chủ tốc, thừa nhân chi bất cập, do bất ngu chi đạo, công kỳ sở bất giới dã.","Xin hỏi: địch đông mà chỉnh tề sắp kéo đến, đối phó thế nào? Đáp: trước hết chiếm lấy điều họ quý nhất, thì họ sẽ phải nghe ta. Vì vậy việc binh cốt ở nhanh: nhân lúc người chưa kịp, đi đường họ không ngờ, đánh chỗ họ không phòng."],["是故散地則無戰輕地則無止爭地則無攻交地則無絕衢地則合交重地則掠圮地則行圍地則謀死地則戰","Thị cố tán địa tắc vô chiến, khinh địa tắc vô chỉ, tranh địa tắc vô công, giao địa tắc vô tuyệt, cù địa tắc hợp giao, trọng địa tắc lược, bĩ địa tắc hành, vi địa tắc mưu, tử địa tắc chiến.","Vì vậy ở đất tan thì không đánh, đất nhẹ thì không dừng, đất tranh thì không tấn công khi địch đã chiếm, đất giao thì không để đội hình bị cắt, đất ngã tư thì kết giao, đất nặng thì lấy lương tại chỗ, đất lở thì đi nhanh, đất vây thì dùng mưu, đất chết thì đánh."],["能使敵自至者利之也能使敵不得至者害之也故敵佚能勞之飽能饑之安能動之出其所不趨趨其所不意","Năng sử địch tự chí giả, lợi chi dã; năng sử địch bất đắc chí giả, hại chi dã. Cố địch dật năng lao chi, bão năng cơ chi, an năng động chi. Xuất kỳ sở bất xu, xu kỳ sở bất ý.","Khiến địch tự đến được là nhờ cho họ thấy lợi; khiến địch không đến được là nhờ cho họ thấy hại. Vì vậy địch đang thong thả thì làm cho mệt, đang no thì làm cho đói, đang yên thì làm cho động. Đi đến chỗ địch không kịp chạy tới, chạy tới chỗ địch không ngờ."],["行火必有因烟火必素具發火有時起火有日時者天之燥也日者月在箕壁翼軫也凡此四宿者風起之日也","Hành hoả tất hữu nhân, yên hoả tất tố cụ. Phát hoả hữu thời, khởi hoả hữu nhật. Thời giả, thiên chi táo dã. Nhật giả, nguyệt tại Cơ, Bích, Dực, Chẩn dã. Phàm thử tứ tú giả, phong khởi chi nhật dã.","Dùng lửa phải có điều kiện, vật dẫn lửa phải chuẩn bị sẵn. Phát lửa có lúc, nổi lửa có ngày. Lúc là khi trời khô hanh. Ngày là khi trăng ở các sao Cơ, Bích, Dực, Chẩn — bốn sao ấy là ngày nổi gió."],["故備前則後寡備後則前寡備左則右寡備右則左寡無所不備則無所不寡寡者備人者也衆者使人備己者也","Cố bị tiền tắc hậu quả, bị hậu tắc tiền quả, bị tả tắc hữu quả, bị hữu tắc tả quả, vô sở bất bị, tắc vô sở bất quả. Quả giả, bị nhân giả dã; chúng giả, sử nhân bị kỷ giả dã.","Phòng mặt trước thì mặt sau mỏng, phòng mặt sau thì mặt trước mỏng, phòng trái thì phải mỏng, phòng phải thì trái mỏng; không chỗ nào không phòng thì không chỗ nào không mỏng. Ít quân là vì phải phòng người; đông quân là vì khiến người phải phòng mình."],["古之所謂善戰者勝於易勝者也故善戰者之勝也無智名無勇功故其戰勝不忒不忒者其所措必勝勝已敗者也","Cổ chi sở vị thiện chiến giả, thắng ư dị thắng giả dã. Cố thiện chiến giả chi thắng dã, vô trí danh, vô dũng công. Cố kỳ chiến thắng bất thắc. Bất thắc giả, kỳ sở thố tất thắng, thắng dĩ bại giả dã.","Người xưa gọi là giỏi đánh, là người thắng ở chỗ dễ thắng. Nên cái thắng của người giỏi không có tiếng khôn, không có công dũng cảm. Cái thắng của họ không sai lệch. Không sai lệch là vì cách họ bố trí ắt phải thắng — họ thắng kẻ đã thua sẵn."],["故我欲戰敵雖高壘深溝不得不與我戰者攻其所必救也我不欲戰雖畫地而守之敵不得與我戰者乖其所之也","Cố ngã dục chiến, địch tuy cao luỹ thâm câu, bất đắc bất dữ ngã chiến giả, công kỳ sở tất cứu dã; ngã bất dục chiến, tuy hoạch địa nhi thủ chi, địch bất đắc dữ ngã chiến giả, quai kỳ sở chi dã.","Vì vậy khi ta muốn đánh, địch dù luỹ cao hào sâu cũng phải ra đánh với ta, là vì ta đánh vào chỗ họ buộc phải cứu; khi ta không muốn đánh, dù chỉ vạch đất mà giữ, địch cũng không đánh được ta, là vì ta làm lệch hướng họ định đi."],["昔殷之興也伊摯在夏周之興也呂牙在殷故明君賢將能以上智為間者必成大功此兵之要三軍之所恃而動也","Tích Ân chi hưng dã, Y Chí tại Hạ; Chu chi hưng dã, Lữ Nha tại Ân. Cố minh quân hiền tướng, năng dĩ thượng trí vi gián giả, tất thành đại công. Thử binh chi yếu, tam quân chi sở thị nhi động dã.","Xưa nhà Ân dấy lên là nhờ Y Chí từng ở nhà Hạ; nhà Chu dấy lên là nhờ Lữ Nha từng ở nhà Ân. Vì vậy vua sáng tướng hiền biết dùng người trí tuệ bậc cao làm gián điệp thì tất thành công lớn. Đó là chỗ cốt yếu của việc binh, là chỗ ba quân dựa vào mà hành động."],["是故其兵不修而戒不求而得不約而親不令而信禁祥去疑至死無所之吾士無餘財非惡貨也無餘命非惡壽也","Thị cố kỳ binh bất tu nhi giới, bất cầu nhi đắc, bất ước nhi thân, bất lệnh nhi tín. Cấm tường khứ nghi, chí tử vô sở chi. Ngô sĩ vô dư tài, phi ố hoá dã; vô dư mệnh, phi ố thọ dã.","Vì vậy quân ấy không cần chỉnh đốn mà tự cảnh giác, không cần đòi mà tự có, không cần ràng buộc mà thân nhau, không cần ra lệnh mà tin nhau. Cấm bói toán điềm lạ, dẹp bỏ nghi ngờ, đến chết cũng không lung lay. Quân ta không giữ của dư, không phải vì ghét của; không tiếc mạng, không phải vì ghét sống."],["重地吾將繼其食圮地吾將進其途圍地吾將塞其闕死地吾將示之以不活故兵之情圍則禦不得已則鬥過則從","Trọng địa, ngô tương kế kỳ thực; bĩ địa, ngô tương tiến kỳ đồ; vi địa, ngô tương tắc kỳ khuyết; tử địa, ngô tương thị chi dĩ bất hoạt. Cố binh chi tình: vi tắc ngự, bất đắc dĩ tắc đấu, quá tắc tòng.","Đất nặng, ta sẽ bảo đảm nguồn lương; đất lở, ta sẽ đi nhanh qua; đất vây, ta sẽ lấp lối hở để quân không nghĩ đến chạy; đất chết, ta sẽ cho quân thấy không đánh thì không sống. Tâm lý của quân là: bị vây thì chống, bất đắc dĩ thì đánh, nguy quá thì nghe theo."],["夫未戰而廟算勝者得算多也未戰而廟算不勝者得算少也多算勝少算不勝而況於無算乎吾以此觀之勝負見矣","Phù vị chiến nhi miếu toán thắng giả, đắc toán đa dã; vị chiến nhi miếu toán bất thắng giả, đắc toán thiểu dã. Đa toán thắng, thiểu toán bất thắng, nhi huống ư vô toán hồ? Ngô dĩ thử quan chi, thắng phụ kiến hĩ.","Chưa đánh mà tính toán ở miếu đường đã thấy thắng, là vì điều kiện thắng nhiều; chưa đánh mà tính đã thấy không thắng, là vì điều kiện thắng ít. Tính nhiều thì thắng, tính ít thì không thắng, nói gì đến không tính! Ta xem đó mà thấy trước được thắng bại."],["故校之以七計而索其情曰主孰有道將孰有能天地孰得法令孰行兵眾孰強士卒孰練賞罰孰明吾以此知勝負矣","Cố giảo chi dĩ thất kế nhi sách kỳ tình, viết: chủ thục hữu đạo? Tướng thục hữu năng? Thiên địa thục đắc? Pháp lệnh thục hành? Binh chúng thục cường? Sĩ tốt thục luyện? Thưởng phạt thục minh? Ngô dĩ thử tri thắng phụ hĩ.","Rồi so sánh bằng bảy điều để tìm thực tình: bên nào vua có đạo? Bên nào tướng có tài? Bên nào được thời được đất? Bên nào pháp lệnh được thi hành? Bên nào quân đông mạnh? Bên nào binh sĩ được luyện kỹ? Bên nào thưởng phạt rõ ràng? Ta nhờ đó mà biết thắng bại."],["紛紛紜紜鬥亂而不可亂也渾渾沌沌形圓而不可敗也亂生於治怯生於勇弱生於強治亂數也勇怯勢也強弱形也","Phân phân vân vân, đấu loạn nhi bất khả loạn dã; hồn hồn độn độn, hình viên nhi bất khả bại dã. Loạn sinh ư trị, khiếp sinh ư dũng, nhược sinh ư cường. Trị loạn, số dã; dũng khiếp, thế dã; cường nhược, hình dã.","Rối rối bời bời, đánh giữa chỗ loạn mà mình không loạn; mù mù mịt mịt, thế trận tròn trịa mà không thể bị phá. Loạn là từ trị mà sinh ra, nhát là từ dũng mà sinh ra, yếu là từ mạnh mà sinh ra. Trị hay loạn là do tổ chức; dũng hay nhát là do thế; mạnh hay yếu là do hình."],["以治待亂以靜待嘩此治心者也以近待遠以佚待勞以飽待饑此治力者也無邀正正之旗無擊堂堂之陣此治變者也","Dĩ trị đãi loạn, dĩ tĩnh đãi hoa, thử trị tâm giả dã; dĩ cận đãi viễn, dĩ dật đãi lao, dĩ bão đãi cơ, thử trị lực giả dã; vô yêu chính chính chi kỳ, vô kích đường đường chi trận, thử trị biến giả dã.","Lấy nghiêm chỉnh đón hỗn loạn, lấy yên tĩnh đón ồn ào — đó là trị tâm; lấy gần đón xa, lấy nhàn đón mệt, lấy no đón đói — đó là trị sức; không đón đánh cờ xí chỉnh tề, không đánh vào trận thế đường hoàng — đó là trị biến."],["凡火攻必因五火之變而應之火發於內則早應之於外火發而其兵靜者待而勿攻極其火力可從而從之不可從則止","Phàm hoả công, tất nhân ngũ hoả chi biến nhi ứng chi: hoả phát ư nội, tắc tảo ứng chi ư ngoại; hoả phát nhi kỳ binh tĩnh giả, đãi nhi vật công, cực kỳ hoả lực, khả tòng nhi tòng chi, bất khả tòng tắc chỉ;","Đánh bằng lửa phải tuỳ theo biến chuyển của năm cách mà ứng phó: lửa phát từ bên trong thì sớm ứng từ bên ngoài; lửa đã phát mà quân địch vẫn yên thì chờ, đừng đánh, để lửa cháy hết sức rồi xem có thể theo thì theo, không thể theo thì dừng;"],["視卒如嬰兒故可以與之赴深溪視卒如愛子故可與之俱死厚而不能使愛而不能令亂而不能治譬若驕子不可用也","Thị tốt như anh nhi, cố khả dĩ dữ chi phó thâm khê; thị tốt như ái tử, cố khả dữ chi câu tử. Hậu nhi bất năng sử, ái nhi bất năng lệnh, loạn nhi bất năng trị, thí nhược kiêu tử, bất khả dụng dã.","Coi lính như trẻ nhỏ, nên có thể cùng họ xuống khe sâu; coi lính như con yêu, nên có thể cùng họ sống chết. Nhưng hậu đãi mà không sai được, yêu thương mà không ra lệnh được, rối loạn mà không trị được, thì khác gì con hư — không dùng được."],["孫子曰凡地形有通者有掛者有支者有隘者有險者有遠者我可以往彼可以來曰通通形者先居高陽利糧道以戰則利","Tôn Tử viết: phàm địa hình hữu thông giả, hữu quải giả, hữu chi giả, hữu ải giả, hữu hiểm giả, hữu viễn giả. Ngã khả dĩ vãng, bỉ khả dĩ lai, viết thông. Thông hình giả, tiên cư cao dương, lợi lương đạo, dĩ chiến tắc lợi.","Tôn Tử nói: địa hình có loại thông, loại treo, loại chia, loại hẹp, loại hiểm, loại xa. Ta đến được, địch cũng đến được, gọi là thông. Ở đất thông thì chiếm trước chỗ cao sáng, giữ thuận đường lương, rồi đánh thì lợi."],["孫子曰凡用兵之法全國為上破國次之全軍為上破軍次之全旅為上破旅次之全卒為上破卒次之全伍為上破伍次之","Tôn Tử viết: phàm dụng binh chi pháp, toàn quốc vi thượng, phá quốc thứ chi; toàn quân vi thượng, phá quân thứ chi; toàn lữ vi thượng, phá lữ thứ chi; toàn tốt vi thượng, phá tốt thứ chi; toàn ngũ vi thượng, phá ngũ thứ chi.","Tôn Tử nói: phép dùng binh, giữ được cả nước địch nguyên vẹn là hơn hết, phá nước địch là kém hơn; giữ nguyên cả quân địch là hơn, phá quân địch là kém; với lữ, với tốt, với ngũ cũng vậy — giữ nguyên là hơn, phá là kém."],["故戰道必勝主曰無戰必戰可也戰道不勝主曰必戰無戰可也是故進不求名退不避罪唯民是保而利合於主國之寶也","Cố chiến đạo tất thắng, chủ viết vô chiến, tất chiến khả dã; chiến đạo bất thắng, chủ viết tất chiến, vô chiến khả dã. Thị cố tiến bất cầu danh, thoái bất tị tội, duy dân thị bảo, nhi lợi hợp ư chủ, quốc chi bảo dã.","Vì vậy xét thế trận chắc thắng, dù vua bảo đừng đánh, vẫn có thể đánh; xét thế trận không thắng, dù vua bảo phải đánh, vẫn có thể không đánh. Cho nên tiến không vì cầu danh, lui không sợ mang tội, chỉ cốt bảo vệ dân mà lợi cho vua — người như vậy là báu vật của nước."],["絕水必遠水客絕水而來勿迎之于水內令半濟而擊之利欲戰者無附于水而迎客視生處高無迎水流此處水上之軍也","Tuyệt thuỷ tất viễn thuỷ, khách tuyệt thuỷ nhi lai, vật nghênh chi vu thuỷ nội, lệnh bán tế nhi kích chi, lợi; dục chiến giả, vô phụ vu thuỷ nhi nghênh khách, thị sinh xử cao, vô nghênh thuỷ lưu, thử xử thuỷ thượng chi quân dã.","Qua sông rồi phải đóng xa sông; địch qua sông đến, đừng đón đánh ngay trong nước, đợi họ sang được nửa mà đánh thì lợi; muốn đánh thì đừng sát mé nước mà đón địch; chọn nơi sáng mà ở cao, đừng ở phía dưới dòng nước — đó là cách đóng quân ở vùng sông nước."],["故形人而我無形則我專而敵分我專為一敵分為十是以十攻其一也則我衆而敵寡能以衆擊寡者則吾之所與戰者約矣","Cố hình nhân nhi ngã vô hình, tắc ngã chuyên nhi địch phân. Ngã chuyên vi nhất, địch phân vi thập, thị dĩ thập công kỳ nhất dã, tắc ngã chúng nhi địch quả. Năng dĩ chúng kích quả giả, tắc ngô chi sở dữ chiến giả, ước hĩ.","Vì vậy làm cho địch lộ hình mà ta không lộ hình, thì ta tập trung mà địch phân tán. Ta dồn làm một, địch chia làm mười, thế là lấy mười đánh một, nên ta đông mà địch ít. Lấy đông đánh ít được, thì kẻ phải giao chiến với ta chỉ còn là một phần nhỏ."],["故明君賢將所以動而勝人成功出於眾者先知也先知者不可取於鬼神不可象於事不可驗於度必取於人知敵之情者也","Cố minh quân hiền tướng, sở dĩ động nhi thắng nhân, thành công xuất ư chúng giả, tiên tri dã. Tiên tri giả, bất khả thủ ư quỷ thần, bất khả tượng ư sự, bất khả nghiệm ư độ, tất thủ ư nhân, tri địch chi tình giả dã.","Vua sáng tướng hiền sở dĩ động là thắng, thành công vượt hẳn người thường, là nhờ biết trước. Biết trước không thể cầu ở quỷ thần, không thể suy từ việc tương tự, không thể nghiệm bằng phép đo đếm, mà nhất định phải lấy từ người — người biết tình hình của địch."],["故殺敵者怒也取敵之利者貨也故車戰得車十乘以上賞其先得者而更其旌旗車雜而乘之卒善而養之是謂勝敵而益強","Cố sát địch giả, nộ dã; thủ địch chi lợi giả, hoá dã. Cố xa chiến, đắc xa thập thặng dĩ thượng, thưởng kỳ tiên đắc giả, nhi canh kỳ tinh kỳ. Xa tạp nhi thừa chi, tốt thiện nhi dưỡng chi, thị vị thắng địch nhi ích cường.","Quân giết được địch là nhờ căm giận; lấy được của địch là nhờ có thưởng. Vì vậy đánh bằng xe, hễ bắt được từ mười cỗ xe trở lên thì thưởng người lấy được đầu tiên, rồi thay cờ hiệu của ta vào. Xe địch trộn vào mà dùng, lính địch đối xử tốt mà nuôi — thế gọi là thắng địch mà càng thêm mạnh."],["杖而立者饑也汲而先飲者渴也見利而不進者勞也鳥集者虛也夜呼者恐也軍擾者將不重也旌旗動者亂也吏怒者倦也","Trượng nhi lập giả, cơ dã; cấp nhi tiên ẩm giả, khát dã; kiến lợi nhi bất tiến giả, lao dã; điểu tập giả, hư dã; dạ hô giả, khủng dã; quân nhiễu giả, tướng bất trọng dã; tinh kỳ động giả, loạn dã; lại nộ giả, quyện dã;","Lính chống gậy mà đứng là đang đói; đi lấy nước mà uống trước là đang khát; thấy lợi mà không tiến là đã mệt; chim đậu trên trại là trại đã bỏ trống; đêm có tiếng kêu là đang sợ; quân nhốn nháo là tướng không có uy; cờ xí lay động lộn xộn là đang rối; quan nhỏ hay nổi giận là đã mỏi mệt;"],["辭卑而益備者進也辭強而進驅者退也輕車先出居其側者陣也無約而請和者謀也奔走而陳兵者期也半進半退者誘也","Từ ti nhi ích bị giả, tiến dã; từ cường nhi tiến khu giả, thoái dã; khinh xa tiên xuất, cư kỳ trắc giả, trận dã; vô ước nhi thỉnh hoà giả, mưu dã; bôn tẩu nhi trần binh giả, kỳ dã; bán tiến bán thoái giả, dụ dã;","Lời lẽ nhún nhường mà càng tăng phòng bị là sắp tiến đánh; lời lẽ cứng rắn mà làm bộ xông lên là sắp rút; xe nhẹ ra trước, đứng hai bên là đang dàn trận; chưa có thoả thuận gì mà xin hoà là có mưu; chạy vội mà bày binh là đã hẹn ngày đánh; nửa tiến nửa lui là đang dụ;"],["故善用兵者屈人之兵而非戰也拔人之城而非攻也毀人之國而非久也必以全爭於天下故兵不頓而利可全此謀攻之法也","Cố thiện dụng binh giả, khuất nhân chi binh nhi phi chiến dã, bạt nhân chi thành nhi phi công dã, huỷ nhân chi quốc nhi phi cửu dã, tất dĩ toàn tranh ư thiên hạ, cố binh bất đốn nhi lợi khả toàn, thử mưu công chi pháp dã.","Vì vậy người giỏi dùng binh khiến quân địch khuất phục mà không phải giao chiến, hạ thành địch mà không phải vây đánh, diệt nước địch mà không phải kéo dài; nhất định tranh với thiên hạ bằng cách giữ cho trọn, nên quân không mòn mà lợi được đủ. Đó là phép đánh bằng mưu."],["是故不知諸侯之謀者不能豫交不知山林險阻沮澤之形者不能行軍不用鄉導者不能得地利四五者不知一非霸王之兵也","Thị cố bất tri chư hầu chi mưu giả, bất năng dự giao; bất tri sơn lâm, hiểm trở, tự trạch chi hình giả, bất năng hành quân; bất dụng hương đạo giả, bất năng đắc địa lợi. Tứ ngũ giả, bất tri nhất, phi bá vương chi binh dã.","Vì vậy không biết mưu tính của các nước thì không thể tính trước việc giao kết; không biết hình thế rừng núi, hiểm trở, đầm lầy thì không thể hành quân; không dùng người dẫn đường bản địa thì không lấy được lợi của đất. Trong các điều trên, không biết dù một điều, cũng chưa phải là quân của bậc bá vương."],["故善戰者立於不敗之地而不失敵之敗也是故勝兵先勝而後求戰敗兵先戰而後求勝善用兵者修道而保法故能為勝敗之政","Cố thiện chiến giả, lập ư bất bại chi địa, nhi bất thất địch chi bại dã. Thị cố thắng binh tiên thắng nhi hậu cầu chiến, bại binh tiên chiến nhi hậu cầu thắng. Thiện dụng binh giả, tu đạo nhi bảo pháp, cố năng vi thắng bại chi chính.","Vì vậy người giỏi đánh đứng ở chỗ không thể thua, mà không bỏ lỡ lúc địch bại. Cho nên quân thắng là thắng trước rồi mới tìm đánh; quân thua là đánh trước rồi mới tìm cách thắng. Người giỏi dùng binh sửa đạo giữ pháp, nên nắm được việc thắng bại."],["故知勝有五知可以戰與不可以戰者勝識衆寡之用者勝上下同欲者勝以虞待不虞者勝將能而君不御者勝此五者知勝之道也","Cố tri thắng hữu ngũ: tri khả dĩ chiến dữ bất khả dĩ chiến giả thắng, thức chúng quả chi dụng giả thắng, thượng hạ đồng dục giả thắng, dĩ ngu đãi bất ngu giả thắng, tướng năng nhi quân bất ngự giả thắng. Thử ngũ giả, tri thắng chi đạo dã.","Biết trước thắng có năm điều: biết lúc nào nên đánh, lúc nào không nên — thắng; biết dùng quân đông hay quân ít cho đúng cách — thắng; trên dưới cùng một ý muốn — thắng; lấy sự chuẩn bị đón kẻ không chuẩn bị — thắng; tướng có tài mà vua không kìm kẹp — thắng. Năm điều đó là đường biết trước thắng."],["不知三軍之事而同三軍之政則軍士惑矣不知三軍之權而同三軍之任則軍士疑矣三軍既惑且疑則諸侯之難至矣是謂亂軍引勝","Bất tri tam quân chi sự, nhi đồng tam quân chi chính, tắc quân sĩ hoặc hĩ; bất tri tam quân chi quyền, nhi đồng tam quân chi nhiệm, tắc quân sĩ nghi hĩ. Tam quân ký hoặc thả nghi, tắc chư hầu chi nạn chí hĩ, thị vị loạn quân dẫn thắng.","Không hiểu việc trong quân mà can dự vào việc cai quản quân, thì binh sĩ hoang mang; không hiểu quyền biến trong quân mà can dự vào việc bổ nhiệm, thì binh sĩ nghi ngờ. Quân đã hoang mang lại nghi ngờ thì các nước lân bang kéo đến gây hoạ — thế gọi là làm rối quân mình, dâng chiến thắng cho địch."],["孫子曰凡用兵之法馳車千駟革車千乘帶甲十萬千里饋糧則內外之費賓客之用膠漆之材車甲之奉日費千金然後十萬之師舉矣","Tôn Tử viết: phàm dụng binh chi pháp, trì xa thiên tứ, cách xa thiên thặng, đới giáp thập vạn, thiên lý quỹ lương, tắc nội ngoại chi phí, tân khách chi dụng, giao tất chi tài, xa giáp chi phụng, nhật phí thiên kim, nhiên hậu thập vạn chi sư cử hĩ.","Tôn Tử nói: phép dùng binh, xe nhanh nghìn cỗ, xe bọc nghìn chiếc, quân mang giáp mười vạn, chở lương đi nghìn dặm; chi phí trong ngoài, việc tiếp đãi sứ khách, vật liệu keo sơn, bảo dưỡng xe giáp — mỗi ngày tốn nghìn vàng, rồi mới dấy được đạo quân mười vạn."],["所謂古之善用兵者能使敵人前後不相及衆寡不相恃貴賤不相救上下不相收卒離而不集兵合而不齊合於利而動不合於利而止","Sở vị cổ chi thiện dụng binh giả, năng sử địch nhân tiền hậu bất tương cập, chúng quả bất tương thị, quý tiện bất tương cứu, thượng hạ bất tương thu, tốt ly nhi bất tập, binh hợp nhi bất tề. Hợp ư lợi nhi động, bất hợp ư lợi nhi chỉ.","Người giỏi dùng binh thời xưa khiến địch trước sau không tiếp ứng được nhau, đông và ít không dựa được vào nhau, sang và hèn không cứu được nhau, trên dưới không gom được nhau, lính tan mà không tụ lại được, quân hợp mà không đều. Hợp với lợi thì động, không hợp với lợi thì dừng."],["攻城之法為不得已修櫓轒轀具器械三月而後成距闉又三月而後已將不勝其忿而蟻附之殺士三分之一而城不拔者此攻之災也","Công thành chi pháp, vi bất đắc dĩ. Tu lỗ phần uân, cụ khí giới, tam nguyệt nhi hậu thành; cự nhân, hựu tam nguyệt nhi hậu dĩ. Tướng bất thắng kỳ phẫn, nhi nghĩ phụ chi, sát sĩ tam phân chi nhất, nhi thành bất bạt giả, thử công chi tai dã.","Đánh thành là việc bất đắc dĩ. Sửa thuẫn lớn, đóng xe che, chuẩn bị khí cụ, ba tháng mới xong; đắp núi đất sát thành, lại ba tháng nữa mới xong. Tướng không nén được giận, bắt quân bám tường mà trèo như kiến, chết mất một phần ba mà thành vẫn không hạ — đó là tai hoạ của việc đánh thành."],["凡為客之道深則專淺則散去國越境而師者絕地也四達者衢地也入深者重地也入淺者輕地也背固前隘者圍地也無所往者死地也","Phàm vi khách chi đạo, thâm tắc chuyên, thiển tắc tán. Khứ quốc việt cảnh nhi sư giả, tuyệt địa dã; tứ đạt giả, cù địa dã; nhập thâm giả, trọng địa dã; nhập thiển giả, khinh địa dã; bối cố tiền ải giả, vi địa dã; vô sở vãng giả, tử địa dã.","Phép làm khách trên đất người: vào sâu thì chuyên, vào nông thì tan. Rời nước vượt biên mà đóng quân là đất cô lập; bốn phía thông là đất ngã tư; vào sâu là đất nặng; vào nông là đất nhẹ; sau lưng vững, trước mặt hẹp là đất vây; không còn chỗ đi là đất chết."],["將弱不嚴教道不明吏卒無常陳兵縱橫曰亂將不能料敵以少合衆以弱擊強兵無選鋒曰北凡此六者敗之道也將之至任不可不察也","Tướng nhược bất nghiêm, giáo đạo bất minh, lại tốt vô thường, trần binh túng hoành, viết loạn; tướng bất năng liệu địch, dĩ thiểu hợp chúng, dĩ nhược kích cường, binh vô tuyển phong, viết bắc. Phàm thử lục giả, bại chi đạo dã, tướng chi chí nhiệm, bất khả bất sát dã.","Tướng yếu không nghiêm, dạy dỗ không rõ, quan lính không có nền nếp, bày quân lộn xộn, gọi là rối; tướng không lượng được địch, lấy ít chọi đông, lấy yếu đánh mạnh, quân không có mũi nhọn chọn lọc, gọi là thua. Sáu điều ấy là đường đến thất bại, là trách nhiệm lớn nhất của tướng, không thể không xét kỹ."],["夫霸王之兵伐大國則其衆不得聚威加於敵則其交不得合是故不爭天下之交不養天下之權信己之私威加於敵則其城可拔其國可隳","Phù bá vương chi binh, phạt đại quốc, tắc kỳ chúng bất đắc tụ; uy gia ư địch, tắc kỳ giao bất đắc hợp. Thị cố bất tranh thiên hạ chi giao, bất dưỡng thiên hạ chi quyền, tín kỷ chi tư, uy gia ư địch, tắc kỳ thành khả bạt, kỳ quốc khả huy.","Quân của bậc bá vương đánh nước lớn thì quân nước ấy không kịp tụ lại; uy đè lên địch thì đồng minh của địch không hợp lại được. Vì vậy không cần tranh giành kết giao với thiên hạ, không cần nuôi thế lực khắp thiên hạ, chỉ tin vào sức riêng của mình, uy đè lên địch, thì thành của họ có thể hạ, nước của họ có thể diệt."],["是故軍無輜重則亡無糧食則亡無委積則亡故不知諸侯之謀者不能豫交不知山林險阻沮澤之形者不能行軍不用鄉導者不能得地利","Thị cố quân vô truy trọng tắc vong, vô lương thực tắc vong, vô uỷ tích tắc vong. Cố bất tri chư hầu chi mưu giả, bất năng dự giao; bất tri sơn lâm, hiểm trở, tự trạch chi hình giả, bất năng hành quân; bất dụng hương đạo giả, bất năng đắc địa lợi.","Vì vậy quân không có xe lương thì chết, không có lương ăn thì chết, không có kho dự trữ thì chết. Không biết mưu tính của các nước thì không thể tính trước việc giao kết; không biết hình thế rừng núi, hiểm trở, đầm lầy thì không thể hành quân; không dùng người dẫn đường bản địa thì không thể lấy được lợi thế của đất."],["行千里而不勞者行於無人之地也攻而必取者攻其所不守也守而必固者守其所不攻也故善攻者敵不知其所守善守者敵不知其所攻","Hành thiên lý nhi bất lao giả, hành ư vô nhân chi địa dã. Công nhi tất thủ giả, công kỳ sở bất thủ dã; thủ nhi tất cố giả, thủ kỳ sở bất công dã. Cố thiện công giả, địch bất tri kỳ sở thủ; thiện thủ giả, địch bất tri kỳ sở công.","Đi nghìn dặm mà không mệt là vì đi qua đất không người. Đánh mà chắc lấy được là vì đánh chỗ địch không giữ; giữ mà chắc vững là vì giữ chỗ địch không đánh. Vì vậy người giỏi đánh thì địch không biết phải giữ chỗ nào; người giỏi giữ thì địch không biết nên đánh chỗ nào."],["鄉間者因其鄉人而用之內間者因其官人而用之反間者因其敵間而用之死間者為誑事於外令吾間知之而傳於敵間也生間者反報也","Hương gián giả, nhân kỳ hương nhân nhi dụng chi; nội gián giả, nhân kỳ quan nhân nhi dụng chi; phản gián giả, nhân kỳ địch gián nhi dụng chi; tử gián giả, vi cuống sự ư ngoại, lệnh ngô gián tri chi, nhi truyền ư địch gián dã; sinh gián giả, phản báo dã.","Gián điệp địa phương là dùng người dân nước địch; gián điệp nội bộ là dùng quan lại của địch; gián điệp phản lại là dùng chính gián điệp của địch; gián điệp chết là bày việc giả ở ngoài, cho gián điệp của ta biết rồi truyền sang gián điệp địch; gián điệp sống là người đi rồi trở về báo tin."],["凡軍好高而惡下貴陽而賤陰養生而處實軍無百疾是謂必勝丘陵堤防必處其陽而右背之此兵之利地之助也上雨水沫至欲涉者待其定也","Phàm quân hiếu cao nhi ố hạ, quý dương nhi tiện âm, dưỡng sinh nhi xử thực, quân vô bách tật, thị vị tất thắng. Khâu lăng đê phòng, tất xử kỳ dương, nhi hữu bối chi, thử binh chi lợi, địa chi trợ dã. Thượng vũ, thuỷ mạt chí, dục thiệp giả, đãi kỳ định dã.","Quân ưa chỗ cao ghét chỗ thấp, chuộng nơi sáng bỏ nơi tối, chăm sức khoẻ và đóng ở nơi vững chắc, quân không mắc bệnh — thế gọi là chắc thắng. Gò đồi, bờ đê thì phải đóng ở phía sáng, lấy nó làm chỗ tựa bên phải và sau lưng; đó là lợi của việc binh, là chỗ đất giúp mình. Thượng nguồn mưa, bọt nước trôi xuống, muốn lội qua thì đợi nước lặng."],["故知戰之地知戰之日則可千里而會戰不知戰之地不知戰之日則左不能救右右不能救左前不能救後後不能救前而況遠者數十里近者數里乎","Cố tri chiến chi địa, tri chiến chi nhật, tắc khả thiên lý nhi hội chiến; bất tri chiến chi địa, bất tri chiến chi nhật, tắc tả bất năng cứu hữu, hữu bất năng cứu tả, tiền bất năng cứu hậu, hậu bất năng cứu tiền, nhi huống viễn giả sổ thập lý, cận giả sổ lý hồ!","Vì vậy biết chỗ đánh, biết ngày đánh, thì dù xa nghìn dặm cũng hội quân đánh được; không biết chỗ, không biết ngày, thì cánh trái không cứu được cánh phải, phải không cứu được trái, trước không cứu được sau, sau không cứu được trước — nói gì đến xa thì vài chục dặm, gần thì vài dặm!"],["施無法之賞懸無政之令犯三軍之衆若使一人犯之以事勿告以言犯之以利勿告以害投之亡地然後存陷之死地然後生夫衆陷於害然後能為勝敗","Thi vô pháp chi thưởng, huyền vô chính chi lệnh. Phạm tam quân chi chúng, nhược sử nhất nhân. Phạm chi dĩ sự, vật cáo dĩ ngôn; phạm chi dĩ lợi, vật cáo dĩ hại. Đầu chi vong địa nhiên hậu tồn, hãm chi tử địa nhiên hậu sinh. Phù chúng hãm ư hại, nhiên hậu năng vi thắng bại.","Ban thưởng vượt ngoài lệ thường, ra lệnh vượt ngoài khuôn phép. Điều khiển cả ba quân như sai một người. Giao việc cho họ, không cần giải thích bằng lời; cho họ thấy lợi, không nói đến hại. Đưa vào đất mất rồi mới còn, dồn vào đất chết rồi mới sống. Quân rơi vào chỗ hại rồi mới có thể xoay chuyển thắng bại."],["凡地有絕澗遇天井天牢天羅天陷天隙必亟去之勿近也吾遠之敵近之吾迎之敵背之軍旁有險阻潢井葭葦林木蘙薈者必謹覆索之此伏奸之所處也","Phàm địa hữu tuyệt giản, ngộ thiên tỉnh, thiên lao, thiên la, thiên hãm, thiên khích, tất cức khứ chi, vật cận dã. Ngô viễn chi, địch cận chi; ngô nghênh chi, địch bối chi. Quân bàng hữu hiểm trở, hoàng tỉnh, gia vĩ, lâm mộc, ế hội giả, tất cẩn phúc sách chi, thử phục gian chi sở xử dã.","Gặp khe sâu, gặp những chỗ gọi là giếng trời, ngục trời, lưới trời, hố trời, kẽ trời, thì phải mau rời đi, đừng đến gần. Ta xa chúng, để địch gần chúng; ta quay mặt về phía chúng, để địch quay lưng vào chúng. Bên cạnh nơi đóng quân có chỗ hiểm trở, ao tù, lau sậy, rừng cây, bụi rậm, thì phải lục soát kỹ, vì đó là nơi kẻ gian ẩn nấp."],["入人之地深背城邑多者為重地山林險阻沮澤凡難行之道者為圮地所由入者隘所從歸者迂彼寡可以擊吾之衆者為圍地疾戰則存不疾戰則亡者為死地","Nhập nhân chi địa thâm, bối thành ấp đa giả, vi trọng địa; sơn lâm, hiểm trở, tự trạch, phàm nan hành chi đạo giả, vi bĩ địa; sở do nhập giả ải, sở tòng quy giả vu, bỉ quả khả dĩ kích ngô chi chúng giả, vi vi địa; tật chiến tắc tồn, bất tật chiến tắc vong giả, vi tử địa.","Vào sâu đất người, sau lưng là nhiều thành ấp của họ, là đất nặng; rừng núi, hiểm trở, đầm lầy, mọi đường khó đi, là đất lở; lối vào hẹp, lối về vòng vèo, địch ít mà đánh được số đông của ta, là đất vây; đánh gấp thì sống, không đánh gấp thì chết, là đất chết."],["是故卷甲而趨日夜不處倍道兼行百里而爭利則擒三軍將勁者先疲者後其法十一而至五十里而爭利則蹶上軍將其法半至三十里而爭利則三分之二至","Thị cố quyển giáp nhi xu, nhật dạ bất xử, bội đạo kiêm hành, bách lý nhi tranh lợi, tắc cầm tam quân tướng, kính giả tiên, bì giả hậu, kỳ pháp thập nhất nhi chí; ngũ thập lý nhi tranh lợi, tắc quyết thượng quân tướng, kỳ pháp bán chí; tam thập lý nhi tranh lợi, tắc tam phân chi nhị chí.","Cuốn giáp mà chạy, ngày đêm không nghỉ, đi gấp đôi đường, chạy trăm dặm để tranh lợi thì tướng của ba quân bị bắt, kẻ khoẻ đến trước kẻ mệt rớt sau, thường chỉ một phần mười tới nơi; chạy năm mươi dặm để tranh lợi thì tướng tiên phong gục, chỉ nửa quân tới; chạy ba mươi dặm thì hai phần ba tới."],["諸侯自戰其地者為散地入人之地而不深者為輕地我得則利彼得亦利者為爭地我可以往彼可以來者為交地諸侯之地三屬先至而得天下之衆者為衢地","Chư hầu tự chiến kỳ địa giả, vi tán địa; nhập nhân chi địa nhi bất thâm giả, vi khinh địa; ngã đắc tắc lợi, bỉ đắc diệc lợi giả, vi tranh địa; ngã khả dĩ vãng, bỉ khả dĩ lai giả, vi giao địa; chư hầu chi địa tam thuộc, tiên chí nhi đắc thiên hạ chi chúng giả, vi cù địa;","Đánh ngay trên đất nước mình là đất tan; vào đất người mà chưa sâu là đất nhẹ; ta được thì lợi, địch được cũng lợi là đất tranh; ta đến được, địch đến được là đất giao; đất tiếp giáp nhiều nước, ai đến trước thì được lòng thiên hạ là đất ngã tư;"],["知吾卒之可以擊而不知敵之不可擊勝之半也知敵之可擊而不知吾卒之不可以擊勝之半也知敵之可擊知吾卒之可以擊而不知地形之不可以戰勝之半也","Tri ngô tốt chi khả dĩ kích, nhi bất tri địch chi bất khả kích, thắng chi bán dã; tri địch chi khả kích, nhi bất tri ngô tốt chi bất khả dĩ kích, thắng chi bán dã; tri địch chi khả kích, tri ngô tốt chi khả dĩ kích, nhi bất tri địa hình chi bất khả dĩ chiến, thắng chi bán dã.","Biết quân mình có thể đánh mà không biết địch không thể bị đánh, chỉ nắm được nửa phần thắng; biết địch có thể bị đánh mà không biết quân mình không đánh được, cũng chỉ nửa phần; biết địch có thể bị đánh, biết quân mình đánh được, mà không biết địa hình không cho đánh, vẫn chỉ nửa phần."],["是故政舉之日夷關折符無通其使厲於廊廟之上以誅其事敵人開闔必亟入之先其所愛微與之期踐墨隨敵以決戰事是故始如處女敵人開戶後如脫兔敵不及拒","Thị cố chính cử chi nhật, di quan chiết phù, vô thông kỳ sứ; lệ ư lang miếu chi thượng, dĩ tru kỳ sự. Địch nhân khai hạp, tất cức nhập chi, tiên kỳ sở ái, vi dữ chi kỳ, tiễn mặc tuỳ địch, dĩ quyết chiến sự. Thị cố thủy như xử nữ, địch nhân khai hộ; hậu như thoát thố, địch bất cập cự.","Vì vậy ngày quyết định ra quân, đóng cửa ải, huỷ phù tín, không cho sứ địch qua lại; bàn định kín ở triều đình để quyết việc. Địch hở cửa thì phải vào ngay, nhắm trước điều họ quý, kín đáo định ngày, theo sát tình hình địch mà quyết trận. Vì vậy lúc đầu như gái chưa chồng, khiến địch mở cửa; sau như thỏ sổng, địch không kịp chống."]];
